function save(){if(!game)return;try{localStorage.setItem(KEY,JSON.stringify(game.s));game.checkpointStatus='Saved on this device';if($('saveStatus'))$('saveStatus').textContent=game.checkpointStatus;}catch{game.checkpointStatus='Storage unavailable · save externally';if($('saveStatus'))$('saveStatus').textContent=game.checkpointStatus;}}
function showToast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');}
const battleMessages=createMessagePlayer({show:item=>{presentedEvent=item.event||null;showToast(item.text);if(presentedEvent)renderFrames();},hide:()=>{presentedEvent=null;$('toast').classList.remove('show');if(game)renderFrames();},duration:()=>messageDuration(game?.s),onIdle:()=>queueMicrotask(()=>{syncPlayback();showPendingDecisions();})});
const monthlyMessages=createMessagePlayer({show:()=>{},duration:()=>messageDuration(game?.s)});
const replayMessages=createMessagePlayer({show:()=>{},duration:()=>messageDuration(game?.s)});
function toast(message){if(battleMessages.busy){battleMessages.enqueue(message);syncPlayback();return;}showToast(message);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),messageDuration(game?.s));}
function archiveEvent(e){const existing=game.s.log.find(x=>x.year===game.s.year&&x.month===game.s.month&&x.text===e.text);if(existing)existing.event={...e};else{game.record(e.text,e.kind||'war');game.s.log[0].event={...e};}}
function showBattleMessages(b,serial){if(!b||!game.battleDetailed(b))return;for(const m of b.messages||[])if(m.serial>serial){const event={kind:'war',art:'war',title:`#${b.target} · ${game.province(b.target).name} · Day ${m.day}`,text:m.text};archiveEvent(event);battleMessages.enqueue({text:m.text});}save();}
function syncPlayback(){
 if(!game)return;if($('game').hidden||document.hidden)replayMessages.pause();else replayMessages.resume();const blocked=$('game').hidden||document.hidden||$('dialog').open||!$('cheatHud').hidden;
 blocked?battleMessages.pause():battleMessages.resume();
 const review=game.s.monthlyReview,key=review?`${review.year}:${review.month}:${review.index}`:'';
 if(!key){monthlyMessages.clear();monthlyKey='';return;}
 if(key!==monthlyKey){monthlyMessages.clear();monthlyKey=key;monthlyMessages.enqueue({onDone:advanceMonthlyEvent});}
 blocked||battleMessages.busy?monthlyMessages.pause():monthlyMessages.resume();
}
function setSelected(id,focus=true){const pid=game.province(id).id;if(provinceController?.isAllocating()&&pid!==game.s.selected){toast('Finish troop reassignment before changing provinces.');return false;}if(game.s.battle&&pid!==game.s.battle.target){toast("Finish the battle before changing provinces.");return false;}if(pid!==game.s.selected)pendingFort=null;game.s.selected=pid;game.s.portraitOfficer=null;delete game.s.eventPreview;if(focus)world?.focus(id);render();save();audio?.play('select');return true;}
function button(key){const c=commands[key];return `<button class="command" data-order="${key}"><span class="command-symbol" aria-hidden="true">${c.symbol}</span><span><strong>${c.title}</strong><small>${c.hint}</small></span></button>`;}

function render(){
 audio?.setTheme(game.s.triumph?'triumph':game.battleDetailed()?'battle':'council');$('dialog').classList.toggle('triumph-dialog',!!game.s.triumph);
 $('game').classList.toggle('battle-active',game.battleDetailed());
 const stamp=game.s.player+':'+game.s.turn,battle=game.battleDetailed();
 if(stamp!==turnStamp&&!battle){paneView='turn';game.s.selected=game.ruler().home;const terrainView=view!=='china';view='china';turnStamp=stamp;if(terrainView)buildWorld();world?.overview();}
 if(wasBattle&&!battle){paneView='turn';view='china';buildWorld();}
 wasBattle=battle;
 const p=selected(),owner=game.ruler(p.owner),gov=p.governor===null?null:game.officer(p.governor);
 $('provincePanel').dataset.screen=paneView;
 $('battlePanel').hidden=!battle;
 const body=$('panelBody');(battle?$('battleOrders'):$('eventFrame')).append(body);
 body.hidden=!battle&&paneView==='turn';$('expandEvent').hidden=battle||paneView!=='turn';
 $('date').textContent=`${months[game.s.month-1]} · ${game.s.year} AD`;$('season').textContent=season()[0];$('seasonIcon').textContent=season()[1];
 $('provinceName').innerHTML=`<b class="province-number">${p.id}</b> ${esc(p.name)} <span>${esc(p.zh.split(' · ')[0])}</span>`;
 $('rulerName').textContent=owner?name(owner):'Unclaimed';$('rulerTrust').textContent=owner?owner.trust+' / 100':'—';$('governor').textContent=gov?name(gov):'Unassigned';
 $('mapTitle').textContent=view==='china'?'China':'Province '+p.id;$('mapSubtitle').textContent=view==='china'?'41 cities · tap a number':'#'+p.id+' · '+p.name;
 $('legendOwner').textContent=game.isHuman()?'Your provinces · headquarters blinks':'Active provinces · headquarters blinks';
 if(battle)renderWar();
 else if(paneView==='province')renderProvince();
 else if(paneView==='orders')renderProvinceOrders();
 else if(paneView==='map')renderApproachMap();
 else if(paneView==='events')renderProvinceEvents();
 else body.innerHTML='';
 renderNavigation();
 $('mapMode').textContent=view==='china'?'Province map':'China map';
 renderFrames();const connections=$('provinceConnections');if(connections){connections.hidden=battle||view!=='china'||game.s.settings.showNumbers===false;const p=selected();connections.innerHTML='<span>Routes #'+p.id+'</span>'+p.neighbors.map(id=>'<button data-connection="'+id+'" aria-label="Connected province '+id+'">'+id+'</button>').join('');connections.querySelectorAll('button').forEach(button=>button.onclick=()=>setSelected(Number(button.dataset.connection)));}artwork?.refresh();world?.update();if($('ownershipToggle')){$('ownershipToggle').hidden=battle||view!=='china';$('ownershipToggle').setAttribute('aria-pressed',String(game.s.settings.ownership!==false));$('ownershipToggle').textContent=game.s.settings.ownership===false?'Ownership off':'Ownership on';}if($('numbersToggle')){const visible=game.s.settings.showNumbers!==false;$('numbersToggle').hidden=battle||view!=='china';$('numbersToggle').setAttribute('aria-pressed',String(visible));$('numbersToggle').setAttribute('aria-label',visible?'Hide province numbers':'Show province numbers');$('numbersToggle').title=visible?'Hide province numbers':'Show province numbers';}queueMicrotask(showPendingDecisions);syncPlayback();
}
function navigate(next){pendingFort=null;paneView=next;if(view!=='china'){view='china';buildWorld();}audio.play('select');render();}
function renderNavigation(){
 if(game.roaming()&&!game.s.monthlyReview){$('provinceNavigation').innerHTML='<button id="exileOrders">Exile orders</button><button data-screen="province">View Province</button>';$('exileOrders').onclick=renderExileOrders;$('provinceNavigation').querySelector('[data-screen]').onclick=()=>navigate('province');return;}
 const pending=!!game.s.monthlyReview;if(pending){$('provinceNavigation').innerHTML=`<span class="monthly-progress" role="status">Monthly events · ${game.s.monthlyReview.index+1}/${game.s.lastReport.details.length}</span>`;return;}
 const routes=paneView==='orders'?[['events','Province Events'],['province','Province View']]:['province','map'].includes(paneView)?[['orders','Province Orders'],['events','Events']]:[['events',"This month's events across China"],['province','View Province'],['orders','Province Orders']];
 $('provinceNavigation').innerHTML=routes.map(([id,label])=>`<button data-screen="${id}" ${pending&&id==='orders'?'disabled':''}>${label}</button>`).join('');
 if(game.s.captiveDecisions.some(c=>game.isHuman(c.owner))){const button=document.createElement('button');button.id='reviewCaptives';button.textContent='Decide captives';button.className='gold-button';button.onclick=()=>{$('dialog').close();showPendingDecisions();};$('provinceNavigation').append(button);}else if(game.s.journey){const button=document.createElement('button');button.id='reviewJourney';button.textContent='Messenger journey';button.onclick=()=>{$('dialog').close();showPendingDecisions();};$('provinceNavigation').append(button);}
 $('provinceNavigation').querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>navigate(b.dataset.screen));
}
function provinceMetrics(p){return [['Pop',num(p.population)],['Men',num(p.officers.reduce((n,id)=>n+game.officer(id).soldiers,0))],['Generals',p.officers.length],['Free Gen',p.unclaimed.length],['Gold',num(p.gold)],['Food',num(p.food)],['Rate',p.ricePrice],['Horses',p.horses],['Loy',p.loyalty],['Land',p.land],['Flood',p.flood],['Forts',provinceTerrain(p,terrains[p.id-1]).filter(t=>t===5).length]];}
function renderApproachMap(){const p=selected(),source=game.province(game.mapApproachProvince||p.neighbors[0]);$('panelBody').innerHTML=`<h2 class="approach-title">#${p.id} · ${esc(p.name)} battlefield</h2><p class="dialog-intro">${pendingFort?'Choose a plain or hill hex to build the fort. Placement costs 100 gold and uses the selected builder’s action.':'Choose a connected province. Gold hexes mark its legal attacking deployment edge.'}</p><div class="approach-options">${p.neighbors.map(id=>{const q=game.province(id),dir=provinceDirection(p,q);return `<button data-approach="${id}" class="${id===source.id?'active':''}"><strong>${esc(provinceOwnerLabel(game,q))}</strong><small>${esc(DIRECTIONS[dir].label)} edge</small></button>`;}).join('')}</div>`;if(pendingFort){const cancel=document.createElement('button');cancel.id='cancelFortPlacement';cancel.textContent='Cancel fort placement';cancel.onclick=()=>{pendingFort=null;render();};$('panelBody').prepend(cancel);}$('panelBody').querySelectorAll('[data-approach]').forEach(b=>b.onclick=()=>{game.mapApproachProvince=Number(b.dataset.approach);world.update();renderApproachMap();});}
function renderProvince(){const p=selected();$('panelBody').innerHTML=`<dl class="province-attributes">${provinceMetrics(p).map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
const provinceOrders=[['rest','Rest'],['move','Move'],['transport','Send'],['war','War'],['military','Milit'],['personnel','Person'],['diplomacy','Diplom'],['spy','Spy'],['view','View'],['develop','Cultiv'],['flood','Flood'],['reward','Reward'],['relief','Give'],['trade','Merch'],['tax','Tax'],['map','Map'],['delegate','Deleg'],['exile','Exile'],['advice','Advice']];
function renderProvinceOrders(){if(game.roaming()){renderExileOrders();return;}const permitted=owns(selected())&&game.isHuman();const readOnly=['view','map'];$('panelBody').innerHTML=`<div class="province-orders">${provinceOrders.map(([id,label],i)=>`<button data-command="${id}" class="${orderUnavailable(game,selected(),id)?'order-unavailable':''}" ${!permitted&&!readOnly.includes(id)?'disabled':''}><small>${i+1}</small><span>${label}</span></button>`).join('')}</div>${!owns(selected())?'<p class="dialog-intro">Choose one of your provinces to issue orders.</p>':''}${game.s.monthlyReview?'<p class="dialog-intro">Read the monthly council before issuing orders.</p>':''}`;$('panelBody').querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>provinceCommand(b.dataset.command));}
function renderProvinceEvents(){
 const s=game.s,report=s.lastReport?.year===s.year&&s.lastReport?.month===s.month?s.lastReport:null;
 const seen=new Set(),items=[...(report?.details||[]),...s.log.filter(e=>e.year===s.year&&e.month===s.month)].filter(e=>{if(seen.has(e.text))return false;seen.add(e.text);return true;});
 $('panelBody').innerHTML=`<div class="events-heading"><h2>${months[s.month-1]} ${s.year}</h2><small>Your provinces are highlighted; ★ marks the ruler’s headquarters.</small></div><div class="province-event-list">${s.provinces.map(p=>{const own=owns(p),capital=p.id===game.ruler().home;const events=items.filter(e=>e.province===p.id||e.text?.startsWith(p.name+':'));return `<article class="province-event ${own?'controlled':''} ${capital?'current-capital':''}"><button data-event-province="${p.id}" aria-label="View ${esc(p.name)}${capital?', ruler’s headquarters':own?', controlled province':''}"><strong>${capital?'★ ':''}#${p.id}</strong><small>${p.owner===255?'Unclaimed':esc(name(game.ruler(p.owner)))}</small></button>${events.length?events.map(e=>`<p>${esc(e.text)}</p>`).join(''):'<p class="muted">No provincial event recorded this month.</p>'}</article>`;}).join('')}${items.filter(e=>!e.province&&!s.provinces.some(p=>e.text?.startsWith(p.name+':'))).map(e=>`<article class="province-event realm-event"><strong>Across China</strong><p>${esc(e.text)}</p></article>`).join('')}</div>`;
 $('panelBody').querySelectorAll('[data-event-province]').forEach(b=>b.onclick=()=>{setSelected(Number(b.dataset.eventProvince));navigate('province');});

}
function provinceCommand(id){const reason=orderUnavailable(game,selected(),id);if(reason){toast(reason);return;}
 if(provinceUI().open(id))return;
 if(id==='rest'){restProvinceDialog();return;}if(id==='view'){navigate('province');return;}if(id==='map'){view=view==='china'?'province':'china';buildWorld();render();return;}
 if(id==='war'){invadeDialog();return;}if(id==='military'){commandGroup('Military orders',['enlist','train','fortify']);return;}
 if(id==='personnel'){personnelDialog();return;}if(id==='advice'){adviceDialog();return;}if(id==='spy'){intelligenceDialog();return;}if(id==='exile'){exileDialog();return;}orderDialog(id);
}
function commandGroup(title,keys){dialog(title,`<div class="commands">${keys.map(button).join('')}</div>`,`<button id="groupClose">Close</button>`,'PROVINCE ORDERS');$('groupClose').onclick=close;$('dialogBody').querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderDialog(b.dataset.order));}
function personnelDialog(){const p=selected();dialog('Personnel',`<div class="commands">${['search','recruit'].map(button).join('')}</div><div class="section-label">SERVING & FREE GENERALS</div>${[...p.officers,...p.unclaimed].map(id=>{const o=game.officer(id);return `<button class="officer-card list-row" data-person="${id}">${portraitMarkup(o,'portrait-mini')}<span class="officer-details"><strong>${esc(name(o))}</strong><small>INT ${o.int} · WAR ${o.war} · ${p.unclaimed.includes(id)?'Free general':o.sick||o.injured?recoveryLabel(o):o.acted?'Acted':'Ready'}</small></span></button>`;}).join('')}`,`<button id="personnelClose">Close</button>`,'PERSON');$('personnelClose').onclick=close;$('dialogBody').querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>officerDialog(Number(b.dataset.person)));$('dialogBody').querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderDialog(b.dataset.order));}
function intelligenceDialog(){const targets=game.s.provinces.filter(p=>!owns(p));dialog('Province intelligence',`${selectField('spyProvince','Scout province',options(targets.map(p=>provinceChoice(game,p))))}<div id="intelligenceReport"></div>`,`<button id="spyClose">Close</button>`,'SPY');const show=()=>{const p=game.province($('spyProvince').value);$('intelligenceReport').innerHTML=`<p class="dialog-intro">Known intelligence · ${esc(p.name)}</p>${provinceMetrics(p).map(([l,v])=>`<div class="metric-row"><span>${l}</span><strong>${v}</strong></div>`).join('')}`;};$('spyProvince').onchange=show;if(targets.length)show();$('spyClose').onclick=close;}
function adviceDialog(){const p=selected(),advisor=game.ruler().advisor===null?null:game.officer(game.ruler().advisor),ready=p.officers.some(id=>!game.officer(id).acted);let key=p.loyalty<70&&p.food>=3000?'relief':p.flood<60&&p.gold>=100?'flood':p.land<80&&p.gold>=100?'develop':p.unclaimed.length&&p.gold>=100?'recruit':p.hidden.length?'search':p.officers.some(id=>game.officer(id).soldiers&&game.officer(id).training<80)?'train':null;dialog('Advice',`<p>${advisor?esc(name(advisor)):'Your council'}: ${!owns(p)?'Choose a province you control.':!ready?'Your officers have completed their monthly actions. Rest to finish your faction’s turn.':key?esc(commands[key].description):'Our province is stable. Review supplies, prepare the army, or rest.'}</p>${key&&ready&&owns(p)&&game.isHuman()&&!game.s.monthlyReview?`<div class="commands">${button(key)}</div>`:''}`,`<button id="adviceClose">Close</button>`,'COUNCIL');$('adviceClose').onclick=close;$('dialogBody').querySelector('[data-order]')?.addEventListener('click',()=>orderDialog(key));}
function exileDialog(){const p=selected(),pool=p.officers.filter(id=>id!==game.ruler().leader);dialog('Exile a general',`<p class="dialog-intro">Dismiss a general from your service. They become a free general here and their soldiers return to the population. The ruler and the last serving officer cannot be dismissed.</p>${selectField('exileOfficer','General',options(pool.map(id=>[id,name(game.officer(id))])))}<p id="exileError" class="form-error" role="alert"></p>`,`<button id="cancelExile">Cancel</button><button id="confirmExile" ${pool.length&&p.officers.length>1?'':'disabled'}>Confirm exile</button>`,'EXILE');$('cancelExile').onclick=close;$('confirmExile').onclick=()=>{try{const message=game.execute('exile',{province:p.id,officer:Number($('exileOfficer').value)});close();refresh();toast(message);}catch(e){$('exileError').textContent=e.message;}};}
function dialog(title,body,footer='',eyebrow='ISSUE AN ORDER'){replayMessages.clear();$('dialogTitle').textContent=title;$('dialogEyebrow').textContent=eyebrow;$('dialogBody').innerHTML=body;$('dialogFooter').innerHTML=footer;$('dialogFooter').hidden=!footer;if(!$('dialog').open)$('dialog').showModal();artwork?.refresh();syncPlayback();}
let provinceController;
function buildFortDialog(){if(pendingFort){pendingFort=null;render();return;}const p=selected(),ready=p.officers.filter(id=>{try{game.ready(p,id);return true;}catch{return false;}});dialog('Build a fort',selectField('fortBuilder','Who will supervise?',options(ready.map(id=>[id,game.officer(id).name])))+'<div id="fortAdvice"></div><p class="dialog-intro">Choose a plain or hill hex on the map. A fort costs 100 gold and uses the builder’s turn.</p>','<button id="cancelFort">Cancel</button><button id="placeFort" class="gold-button">Choose hex</button>','MAP');$('fortBuilder').dataset.purpose='Build fort';const advise=()=>{$('fortAdvice').innerHTML=orderInsight(game,'Build fort',Number($('fortBuilder').value));};$('fortBuilder').onchange=advise;if(ready.length)advise();$('cancelFort').onclick=close;$('placeFort').disabled=!ready.length||p.gold<100;$('placeFort').onclick=()=>{pendingFort={province:p.id,officer:Number($('fortBuilder').value)};close();view='province';paneView='map';buildWorld();render();toast('Choose a plain or hill hex.');};}
function provinceUI(){return provinceController??=createProvinceCommands({getGame:()=>game,getSelected:selected,buildFort:buildFortDialog,dialog,close,refresh,toast,name,esc,num,portraitMarkup,showOfficer:officerDialog,showFamily:royalFamilyDialog,showProvince:id=>{setSelected(id);navigate('province');},onMap:()=>{view='province';paneView='map';game.mapApproachProvince=selected().neighbors[0];buildWorld();render();}});}
const close=()=>{if(provinceController?.guardClose())return;replayMessages.clear();$('dialog').close();syncPlayback();queueMicrotask(showPendingDecisions);};
function options(items,chosen){return items.map(([id,label,meta])=>`<option value="${id}"${meta?.province!==undefined?` data-province="${meta.province}"`:''}${Number(chosen)===Number(id)?' selected':''}${meta===true?' disabled':''}>${esc(label)}</option>`).join('');}
function selectField(id,label,opts){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${opts}</select></div>`;}
function quantity(id,label,max,def=0,step=1){return `<div class="field"><label for="${id}">${label} · <output id="${id}Value">${num(Math.min(max,def))}</output></label><input type="range" name="${id}" id="${id}" min="0" max="${Math.max(0,max)}" step="${step}" value="${Math.min(max,def)}"><small>Available: ${num(max)}</small></div>`;}
function orderDialog(type,forcedOfficer){
 if(provinceUI().open(type,forcedOfficer))return;
 const p=selected(),c=commands[type];if(!game.isHuman()||game.s.battle||game.s.monthlyReview){toast('Province orders are available during your faction’s turn.');return;}if(!owns(p)){toast('Select one of your own provinces to issue an order.');return;}
 const noOfficer=['tax','trade','delegate'].includes(type),canBusy=['reward','book','governor','advisor'].includes(type);const pool=p.officers.map(id=>game.officer(id)).filter(o=>canBusy||(!o.acted&&!o.sick&&!o.injured)).sort((a,b)=>['develop','flood','search','book'].includes(type)?b.int-a.int:b.charm-a.charm);
 let fields='';if(!noOfficer){fields+=selectField('officer','Officer',options(pool.map(o=>[o.id,`${name(o)} · INT ${o.int} · CHA ${o.charm}`]),forcedOfficer));}
 if(c.resource){let max=Math.min(c.cap,p[c.resource]??0);if(type==='enlist'){const o=pool[0];max=o?Math.floor(Math.min(10000-o.soldiers,Math.floor(p.gold/10)*100,Math.floor(p.food/100)*100,p.population/20)/100)*100:0;}fields+=quantity('amount',type==='relief'?'Rice to distribute':type==='enlist'?'Soldiers to enlist':'Gold to spend',max,c.default,type==='enlist'?100:1);}
 if(type==='trade'){fields+=selectField('mode','Trade',`<option value="buy">Buy rice</option><option value="sell">Sell rice</option><option value="horse">Buy horses</option><option value="arms">Buy weapons</option>`);fields+=selectField('officer','Equip officer',options(p.officers.map(id=>[id,name(game.officer(id))])));fields+=quantity('amount','Quantity',0,0);}
 if(type==='recruit')fields+=selectField('target','Invite',options(p.unclaimed.map(id=>{const o=game.officer(id);return [id,`${name(o)} · INT ${o.int} · CHA ${o.charm}`];})));
 if(type==='move'||type==='transport'){
 const destinations=type==='move'?game.s.provinces.filter(q=>p.neighbors.includes(q.id)&&[255,game.s.player].includes(q.owner)):game.s.provinces.filter(q=>owns(q)&&q.id!==p.id&&game.route(p.id,q.id));fields+=selectField('target','Destination',options(destinations.map(q=>provinceChoice(game,q))));fields+=`<div class="form-grid">${quantity('gold','Gold to send',p.gold,0)}${quantity('food','Rice to send',p.food,0,100)}</div>`;
 }
 if(type==='diplomacy'){fields+=selectField('target','Ruler',options(game.s.rulers.filter(r=>r.id!==game.s.player&&game.s.provinces.some(p=>p.owner===r.id)).map(r=>[r.id,`${name(r)} · Hostility ${game.ruler().relations[r.id]??100}`])));fields+=selectField('mode','Mission','<option value="gift">Send a gift</option><option value="alliance">Offer an alliance with a gift</option>');}
 if(type==='delegate')fields+=selectField('mode','Policy',`<option value="manual" ${p.delegate==='manual'?'selected':''}>Direct control</option><option value="domestic" ${p.delegate==='domestic'?'selected':''}>Develop land and dikes</option><option value="people" ${p.delegate==='people'?'selected':''}>People’s welfare</option>`);
 const unavailable=!noOfficer&&!pool.length?'<p class="form-error">All officers here have acted. End the month to give them new orders.</p>':type==='recruit'&&!p.unclaimed.length?'<p class="form-error">No known unaffiliated officers here. Search for talent first.</p>':type==='trade'&&!p.merchant?'<p class="form-error">No merchant is visiting this month.</p>':'';
 dialog(c.title,`<p class="dialog-intro">${c.description}</p><form id="orderForm">${fields}</form>${unavailable}<div id="preview" class="preview-result"></div><div id="orderAdvice"></div><p id="orderError" class="form-error" role="alert"></p>`,`<button id="cancelOrder">Cancel</button><button id="confirmOrder" class="gold-button" ${unavailable?'disabled':''}>Confirm order</button>`);
 const form=$('orderForm');const args=()=>({province:p.id,...Object.fromEntries(new FormData(form))});let tradeMode='';
 function preview(){
 const data=args();$('orderAdvice').innerHTML=data.officer===undefined?'':orderInsight(game,c.title,Number(data.officer),data);form.querySelectorAll('input[type=range]').forEach(input=>{const out=$(input.id+'Value');if(out)out.textContent=num(input.value);});
 if(type==='trade'){
 const mode=$('mode').value;let max=mode==='buy'?Math.min(p.gold*p.ricePrice,3000000-p.food):mode==='sell'?Math.min(p.food,(30000-p.gold)*p.ricePrice):mode==='horse'?Math.min(Math.floor(p.gold/100),100-p.horses):Math.min(p.gold,Math.floor((10000-game.officer($('officer').value).weapons)/100));const changed=tradeMode!==mode;tradeMode=mode;$('amount').max=max;$('officer').closest('.field').hidden=mode!=='arms';if(changed)$('amount').value=Math.min(max,mode==='buy'||mode==='sell'?5000:mode==='horse'?1:10);$('amountValue').textContent=num($('amount').value);$('amount').closest('.field').querySelector('small').textContent='Available: '+num(max);const n=Number($('amount').value);$('preview').textContent=mode==='buy'?`${num(n)} rice costs ${num(Math.ceil(n/p.ricePrice))} gold. Rate: ${p.ricePrice} rice per gold.`:mode==='sell'?`${num(n)} rice earns ${num(Math.floor(n/p.ricePrice))} gold. Rate: ${p.ricePrice} rice per gold.`:mode==='horse'?`${n} horses cost ${n*100} gold.`:`${n*100} weapons cost ${n} gold.`;
 }else if(['develop','flood','relief','reward'].includes(type)&&data.officer!==undefined&&data.officer!==''){const gain=game.preview(type,p.id,Number(data.officer),Number(data.amount));$('preview').textContent=`Expected ${type==='develop'?'land':type==='flood'?'flood protection':'loyalty'} +${gain}${type==='reward'?' to +'+Math.min(gain+1,100-game.officer(data.officer).loyalty):''}. ${type==='reward'?'This does not use the officer’s action.':'Uses this officer’s monthly action.'}`;}
 else if(type==='recruit'&&data.officer&&data.target)$('preview').textContent=`Chance of acceptance: ${game.recruitChance(p,game.officer(data.officer),game.officer(data.target))}%. Cost: 100 gold, including a declined invitation.`;
 else if(type==='tax')$('preview').textContent=`People’s loyalty: ${p.loyalty} → ${Math.max(0,p.loyalty-10)}. Ruler’s trust: ${game.ruler().trust} → ${Math.max(0,game.ruler().trust-5)}.`;
 else if(type==='move'||type==='transport')$('preview').textContent=`Send ${num(data.gold||0)} gold and ${num(data.food||0)} rice. ${type==='move'?'The officer moves with the supplies.':'The escort stays here.'}`;
 else if(type==='delegate')$('preview').textContent='Delegated orders run when you end the month.';
 else if(type==='book')$('preview').textContent='No gold cost. Intelligence increases by 1 when teaching is possible.';
 else $('preview').textContent='Uses this officer’s monthly action.';
 if(type==='enlist'&&data.officer){const o=game.officer(data.officer),max=Math.floor(Math.min(10000-o.soldiers,Math.floor(p.gold/10)*100,Math.floor(p.food/100)*100,p.population/20)/100)*100;$('amount').max=max;if(Number($('amount').value)>max)$('amount').value=max;const n=Number($('amount').value);$('amountValue').textContent=num(n);$('preview').textContent=`${num(n)} recruits cost ${num(n/10)} gold, ${num(n)} rice, and ${num(n)} population.`;}
 }
 form.addEventListener('input',preview);form.addEventListener('change',preview);form.addEventListener('submit',e=>e.preventDefault());preview();$('cancelOrder').onclick=close;$('confirmOrder').onclick=()=>{try{const message=game.execute(type,args());save();render();world.update();close();audio.play(type==='diplomacy'?'message':'order');toast(message);}catch(e){$('orderError').textContent=e.message;}};
}
function officerDialog(id){if(game.s.battle){battleInspect(id);return;}game.s.portraitOfficer=id;renderFrames();const o=game.officer(id),p=selected(),r=game.ruler(),family=game.s.rulers.find(r=>r.leader===id),role=family?'Ruler':id===p.governor?'Governor':id===r.advisor?'Adviser':p.unclaimed.includes(id)?'Unaffiliated officer':'Officer';dialog(name(o),`${portraitMarkup(o,'dialog-portrait')}<p class="dialog-intro">${esc(o.zh)} · ${role} · Age ${game.s.year-o.birth+1}</p><div class="form-grid"><div>${[['Intelligence',o.int],['War skill',o.war],['Charm',o.charm],['Loyalty',o.loyalty]].map(([l,v])=>`<div class="metric-row"><span>${l}</span><strong class="gold">${v}</strong></div>`).join('')}</div><div>${[['Soldiers',num(o.soldiers)],['Weapons',num(o.weapons)],['Training',o.training],['This month',o.sick||o.injured?recoveryLabel(o):o.acted?'Already acted':'Ready']].map(([l,v])=>`<div class="metric-row"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div></div>${family&&game.s.familyMode!=='expanded'?`<div class="family-status"><h3>Daughter</h3><div class="metric-row"><span>Daughters</span><strong>${family.hasDaughter===false?0:1}</strong></div><div class="metric-row"><span>Marriage</span><strong>${family.hasDaughter===false?'No daughter':family.daughterGivenTo===undefined?'Eligible for marriage':'Married to '+esc(game.ruler(family.daughterGivenTo)?.name||'a former ruler')}</strong></div></div>`:''}${(game.s.items||[]).some(x=>x.officer===o.id)?`<p class="dialog-intro">Possessions: ${(game.s.items||[]).filter(x=>x.officer===o.id).map(x=>esc(ITEMS.find(i=>i.id===x.item)?.name)).join(' · ')}</p>`:''}${o.medicalBook?'<p class="dialog-intro">青囊書 · Hua Tuo’s medical book · one-month recovery</p>':''}${owns(p)&&p.officers.includes(id)?`<div class="dialog-buttons">${['reward','book','move','enlist','train'].map(k=>`<button data-officer-order="${k}" ${(o.acted||o.sick||o.injured)&&['move','enlist','train'].includes(k)?'disabled':''}>${commands[k].title}</button>`).join('')}<button id="appointGovernor">Appoint governor</button><button id="appointAdvisor">Appoint adviser</button></div>`:''}`,`<button id="officerClose">Close</button>${family?'<button id="rulerFamily" class="gold-button">Royal Family</button>':''}`,'OFFICER');$('officerClose').onclick=close;$('rulerFamily')?.addEventListener('click',()=>royalFamilyDialog(family.id));$('dialogBody').querySelectorAll('[data-officer-order]').forEach(b=>b.onclick=()=>orderDialog(b.dataset.officerOrder,id));for(const [element,type]of [['appointGovernor','governor'],['appointAdvisor','advisor']])$(element)?.addEventListener('click',()=>{try{toast(game.execute(type,{province:p.id,officer:id}));save();render();close();}catch(e){toast(e.message);}});}
function provinceDialog(){dialog('Choose a province',`<p class="dialog-intro">Tap a province to inspect it. Gold and rice are stored separately in each province.</p>${game.s.provinces.map(p=>`<button class="list-row" data-pick="${p.id}"><span><strong>#${p.id}</strong><small>${p.owner===255?'Unclaimed':esc(name(game.ruler(p.owner)))} · ${p.officers.length} officers</small></span><span class="tag">${owns(p)?'Your realm':''}</span></button>`).join('')}`,'','THE REALM');$('dialogBody').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{setSelected(Number(b.dataset.pick));close();});}
function chronicle(){dialog('Chronicle',game.s.log.length?game.s.log.map((item,i)=>`<button class="chronicle-item" data-chronicle="${i}"><small>${months[item.month-1]} ${item.year} AD</small><span>${esc(item.text)}</span></button>`).join(''):'<p class="dialog-intro">Your orders and monthly reports will be recorded here.</p>','<button id="chronicleClose">Return to game</button>','YOUR CAMPAIGN');$('chronicleClose').onclick=close;$('dialogBody').querySelectorAll('[data-chronicle]').forEach(button=>button.onclick=()=>{const item=game.s.log[Number(button.dataset.chronicle)],detail=game.s.lastReport?.year===item.year&&game.s.lastReport?.month===item.month?game.s.lastReport.details.find(e=>e.text===item.text):null;eventDialog(item.event||detail||{kind:item.type==='war'?'war':item.type==='diplomacy'?'diplomacy':item.type==='prison'?'prison':'council',title:'Chronicle · '+months[item.month-1]+' '+item.year,text:item.text});});}
function endTurn(){if(game.s.journey||game.s.captiveDecisions.some(c=>game.isHuman(c.owner))){showPendingDecisions();return;}if(game.s.campaignEnded){toast('This campaign has ended. Start or load a campaign from Menu.');return;}if(game.s.monthlyReview)return;if(game.s.battle){if(!game.battleHuman()){togglePause();return;}if(game.s.battle.challenge){toast('Choose Accept or Refuse in the challenge panel.');return;}battleOrder(game.s.battle.phase==='deployment'?'deploy':'end');return;}if(!game.isHuman()){togglePause();return;}const ready=game.s.provinces.filter(p=>owns(p)).reduce((n,p)=>n+p.officers.filter(id=>!game.officer(id).acted).length,0);dialog('End your faction’s turn?',`<p class="dialog-intro">${ready} officers still have actions. Delegated provinces use their remaining actions. Other factions then take their turns; upkeep and seasonal income occur after every faction has finished.</p>`,`<button id="keepPlaying">Keep playing</button><button id="advanceMonth" class="gold-button">End turn</button>`,'FACTION COUNCIL');$('keepPlaying').onclick=close;$('advanceMonth').onclick=()=>{game.finishFactionTurn();audio.play('month');close();refresh();if(!game.s.monthlyReview&&!game.s.battle&&game.isHuman())handoff();};}
function help(){dialog('Rule the realm',`<ol class="help-list"><li><b>Explore China.</b> Drag, pinch, and tap a historical seat. Province map opens the original 13 × 12 terrain grid with raster artwork.</li><li><b>Govern.</b> Choose an officer for each order. Most officers have one action per month. Land improves July harvests; dikes prevent floods.</li><li><b>Prepare for war.</b> Enlist, equip, train, and stock rice. Province Orders → War sends commanders to an adjacent enemy; one officer must stay behind.</li><li><b>Deploy.</b> Choose each unit and tap a highlighted hex. Invaders enter from the edge facing their source province; defenders choose passable ground. Confirm both armies’ positions.</li><li><b>Fight.</b> One daily order per unit: Move, Attack, Wait, View, Strategy or Flee. Hex movement and attacks use vertical and diagonal directions, six in total. Normal move spends mobility; Move enemy taunts a hostile general. Attack offers Normal, Simultaneous, Fireball and Charge. Wait stays in place and adds one mobility point.</li><li><b>Mobility.</b> Units start with two points and carry unused points forward. Plain costs two; jungle, hill, water, castle and palace cost three. Mountains are impassable. Finish army orders makes any unused units Wait.</li><li><b>Strategy.</b> Reinforce calls ready reserves from an adjacent friendly province. The army commander can offer a bribe to an enemy general; rulers cannot be bribed. View inspects any unit; each enemy inspection costs 100 gold without using a daily order.</li><li><b>Challenges and flight.</b> On day 1, war 80+ allows a personal challenge. Refusal causes 5% army desertion; the losing duellist is captured. Flee withdraws one unit. The army commander must confirm flight, which withdraws the entire army.</li><li><b>Win.</b> Capture the opposing ruler, occupy the palace, exhaust the opposing soldiers or make every enemy unit flee. Both armies’ orders form one day; unresolved warfare pauses after day 30 and resumes next month.</li><li><b>Fire and jungle.</b> Burning units lose at least 30% of their soldiers daily. Strong winds spread fire across multiple hexes; rain puts out all fires. A stationary jungle unit automatically ambushes a hostile unit arriving at any of the eight surrounding grid positions.</li><li><b>Hotseat.</b> Each selected human controls one ruler on this phone. Finish a faction turn to pass control. Zero humans runs AI versus AI; HUD pauses and resumes AI; Menu → Game Speed controls playback.</li><li><b>Test.</b> HUD pauses AI and edits attributes. Battle edits use its own tab. Resume AI from HUD. Changes are saved.</li><li><b>Exit.</b> Menu → Exit or Esc returns to launch with your campaign saved. Load Game can restore an external file or the device checkpoint, including an unfinished battle.</li></ol><p class="dialog-intro">The 41 sectors retain the original game’s adjacency. Coastline and rivers are geographic; sector seats and historical circuit names are a gameplay abstraction. Terrain textures are illustrative, not surveyed elevation.</p>`,`<button id="helpClose" class="gold-button">Continue</button>`,'HOW TO PLAY');$('helpClose').onclick=close;}
function settings(){dialog('Game menu',`<label class="switch-row" for="soundToggle"><span>Sound effects<small>Selections, orders, messages and battle actions</small></span><input type="checkbox" role="switch" id="soundToggle" ${game.s.settings.sound!==false?'checked':''}></label><label class="switch-row" for="musicToggle"><span>Music<small>Council, battlefield and triumph themes</small></span><input type="checkbox" role="switch" id="musicToggle" ${game.s.settings.music!==false?'checked':''}></label><div class="form-grid">${selectField('quality','Raster resolution','<option value="low">Low</option><option value="balanced">Balanced</option><option value="high">High</option>')}${selectField('battleView','Battle view','<option value="personal">My ruler personally present</option><option value="all">All battles</option>')}${selectField('names','Officer names','<option value="english">English</option><option value="chinese">Chinese</option>')}</div><div class="section-label">GAME SPEED</div><div id="gameSpeed" class="speed-choices" role="group" aria-label="Game Speed">${[[1200,'Slow'],[600,'Normal'],[300,'Fast'],[100,'Very Fast']].map(([speed,label])=>`<button data-speed="${speed}" aria-pressed="${game.s.speed===speed}">${label}</button>`).join('')}</div><div class="section-label">MESSAGE SPEED</div><div id="messageSpeed" class="speed-choices" role="group" aria-label="Message Speed">${MESSAGE_SPEEDS.map(([speed,label])=>`<button data-message-speed="${speed}" aria-pressed="${messageDuration(game.s)===speed}">${label}<small>${speed/1000} sec</small></button>`).join('')}</div><p id="saveStatus" class="dialog-intro">${esc(game.checkpointStatus||'Device checkpoint available')}</p><div class="dialog-buttons"><button id="exportSave">Save Game</button><button id="chronicle">Chronicle</button><button id="royalFamily">Royal Family</button><button id="importSave">Load Game</button><button id="fullscreen">Fullscreen</button><button id="menuHelp">How to play</button>${game.s.battle?'<button id="menuBattleControls">Battle controls</button>':''}${game.s.battle&&game.battleHuman()?'<button id="menuFinishArmy">Finish army orders</button>':''}<button id="exitGame">Exit</button><button id="about">About</button></div>`,`<button id="menuClose" class="gold-button">Return to game</button>`,'ROMANCE OF THE THREE KINGDOMS II');$('gameSpeed').querySelectorAll('[data-speed]').forEach(button=>button.onclick=()=>{game.s.speed=Number(button.dataset.speed);$('gameSpeed').querySelectorAll('[data-speed]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===game.s.speed)));save();scheduleAI();});$('messageSpeed').querySelectorAll('[data-message-speed]').forEach(button=>button.onclick=()=>{game.s.settings.messageSpeed=Number(button.dataset.messageSpeed);$('messageSpeed').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.messageSpeed)===game.s.settings.messageSpeed)));battleMessages.retime();monthlyMessages.retime();replayMessages.retime();save();});$('battleView').value=game.s.settings.battleView||'personal';$('battleView').onchange=()=>{game.s.settings.battleView=$('battleView').value;if(game.s.battle&&!game.battleDetailed()){game.resolveUnwatchedBattle();view='china';buildWorld();}refresh();};$('quality').value=game.s.settings.quality;$('names').value=game.s.settings.names;$('quality').onchange=()=>{game.s.settings.quality=$('quality').value;world.setQuality();save();};$('names').onchange=()=>{game.s.settings.names=$('names').value;render();save();};for(const [id,key]of [['soundToggle','sound'],['musicToggle','music']])$(id).onchange=()=>{game.s.settings[key]=$(id).checked;audio.unlock();audio.configure(game.s.settings);try{localStorage.setItem('rtk2-audio-preferences',JSON.stringify({sound:game.s.settings.sound,music:game.s.settings.music}));}catch{}save();};$('menuClose').onclick=close;if($('menuFinishArmy'))$('menuFinishArmy').textContent=game.battleHuman()?(game.s.battle.phase==='deployment'?'Confirm placement':'Finish army orders'):(game.s.paused?'Resume AI':'Pause AI');$('menuBattleControls')?.addEventListener('click',battleControlsDialog);$('menuFinishArmy')?.addEventListener('click',()=>{close();endTurn();});$('exitGame').onclick=showLaunch;$('fullscreen').onclick=fullscreen;$('exportSave').onclick=exportSave;$('chronicle').onclick=chronicle;$('royalFamily').onclick=()=>royalFamilyDialog(game.s.player);$('importSave').onclick=importSave;$('menuHelp').onclick=help;$('about').onclick=()=>{dialog('About this remaster',`<p class="dialog-intro">An independent remaster inspired by Romance of the Three Kingdoms II. The original map / general / event / instruction arrangement is adapted for landscape touch controls.</p><div class="notice">Scenario data and the 41 province terrain grids derive from <a href="https://github.com/JuQiang/Rotk2_Python" target="_blank" rel="noopener" class="gold">JuQiang’s Rotk2_Python project</a>. Natural Earth supplies physical coastline and rivers. Historical seats label the original gameplay sectors; exact period boundaries are simplified.</div><p class="dialog-intro">All active game graphics use Canvas 2D and raster artwork. Portraits and event scenes are artistic interpretations. All 352 distinct officers have unique portraits. Army animation depicts marching and attacking formations. Relief artwork and regional capitals sit beneath the original map connections. Music and sound effects are original synthesized recordings.</p><p class="dialog-intro">Domestic formulas preserve the implemented source mechanics. Faction AI and tactical combat complete the unfinished systems as remaster rules. No original EGA image or DOS executable is used for display.</p><div class="dialog-buttons"><button id="backMenu">Back to menu</button></div>`,'','THE PROJECT');$('backMenu').onclick=settings;};}

async function fullscreen(){try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();if(globalThis.screen.orientation?.lock)await globalThis.screen.orientation.lock('landscape');}catch{/* iOS browsers use the visible rotate prompt. */}}
async function exportSave(){const state=JSON.parse(JSON.stringify(game.s));delete state.eventPreview;const text=JSON.stringify(state,null,2),filename=`rtk2-${game.s.year}-${game.s.month}.json`;const download=()=>{const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Game save downloaded.');};try{if(typeof window.showSaveFilePicker==='function'){try{const handle=await window.showSaveFilePicker({suggestedName:filename,types:[{description:'RTK2 campaign',accept:{'application/json':['.json']}}]});const file=await handle.createWritable();await file.write(text);await file.close();toast('Saved game to '+handle.name+'.');}catch(e){if(['SecurityError','NotAllowedError','NotSupportedError'].includes(e.name))download();else throw e;}}else download();audio.play('order');}catch(e){if(e.name!=='AbortError')toast('Save failed: '+e.message);}}

function importSave(){const launched=$('game').hidden;dialog('Load Game',`<p class="dialog-intro">Choose a campaign file from your device or an external drive. It replaces the current campaign after validation.</p><div class="field"><label for="saveFile">External campaign file (.json)</label><input type="file" accept=".json,application/json" class="file-input" id="saveFile"></div><p id="importError" class="form-error" role="alert"></p>${savedState?'<button id="loadCheckpoint">Load last device checkpoint</button>':''}`,`<button id="cancelImport">Cancel</button><button id="readSave" class="gold-button">Load Game</button>`,'RESTORE CAMPAIGN');$('cancelImport').onclick=()=>{if(launched)close();else settings();};$('loadCheckpoint')?.addEventListener('click',()=>{start(validateSave(savedState,scenarios,terrains));close();});$('readSave').onclick=async()=>{audio.unlock();try{let file=$('saveFile').files[0];if(!file&&typeof window.showOpenFilePicker==='function'){const [handle]=await window.showOpenFilePicker({multiple:false,types:[{description:'RTK2 campaign',accept:{'application/json':['.json']}}]});file=await handle.getFile();}if(!file)throw Error('Choose a campaign file.');if(file.size>2500000)throw Error('This file is too large to be a campaign save.');const state=validateSave(JSON.parse(await file.text()),scenarios,terrains);start(state);close();toast('Campaign loaded from '+(file.name||'external file')+'.');}catch(e){if(e.name!=='AbortError')$('importError').textContent=e.message;}};}

function start(state){battleMessages.clear();presentedEvent=null;monthlyMessages.clear();monthlyKey='';replayMessages.clear();pendingFort=null;provinceController?.reset();clearTimeout(aiTimer);pendingReinforce=null;battleMode='move';battleMenu='orders';audio.unlock();game=new Game(state,rules,terrains);game.normalize();delete game.s.eventPreview;audio.configure(game.s.settings);audio.setActive(true);$('launch').hidden=true;$('quitScreen').hidden=true;$('game').hidden=false;$('cheatHud').hidden=true;view=state.battle?'province':'china';paneView='turn';turnStamp=state.player+':'+state.turn;wasBattle=!!state.battle;$('game').classList.toggle('battle-active',!!state.battle);try{buildWorld();render();save();registerTools();scheduleAI();}catch(e){audio.stop();world?.destroy();world=null;$('game').hidden=true;$('launch').hidden=false;throw Error('The raster display could not start: '+e.message);}}

function buildWorld(){world?.destroy();const old=$('scene'),canvas=old.cloneNode();old.replaceWith(canvas);world=createRasterWorld(canvas,$('labels'),game,chinaMap,terrains,assets,view,setSelected,onHex);world.setQuality(game.s.settings.quality);$('mapTip').textContent=view==='china'?'Routes show connected provinces':game.s.battle?'Choose a unit and action · Tap a target':'Province terrain · Drag and pinch';}

function advanceMonthlyEvent(){const m=game.s.monthlyReview;if(!m)return;archiveEvent(game.s.lastReport.details[m.index]);m.index++;if(m.index>=game.s.lastReport.details.length){game.s.monthlyReview=null;game.s.lastEvent={...game.s.lastReport.details.at(-1)};game.resumeWars();}audio.play('message');refresh();if(!game.s.monthlyReview&&!game.s.battle&&game.isHuman())handoff();}
function refresh(){if(game.s.battle&&!game.battleDetailed())game.resolveUnwatchedBattle();if(game.battleDetailed()&&view!=='province'){$('game').classList.add('battle-active');view='province';buildWorld();}else world?.update();render();save();}
function scheduleAI(){clearTimeout(aiTimer);if($('game').hidden)return;aiTimer=setTimeout(()=>{
 syncPlayback();if(!game.s.paused&&!document.hidden&&!$('dialog').open&&$('cheatHud').hidden&&!game.s.monthlyReview&&!battleMessages.busy&&((game.s.battle&&!game.battleHuman())||(!game.s.battle&&!game.isHuman()))){
 const wasHuman=game.battleHuman(),oldActor=game.s.player,oldBattle=game.s.battle,serial=oldBattle?.eventSerial||0,oldLog=[...game.s.log];
 try{game.aiStep();refresh();showBattleMessages(oldBattle||game.s.battle,oldBattle?serial:0);if(!game.battleDetailed(oldBattle||game.s.battle)&&!game.s.monthlyReview){for(const entry of newLogEntries(oldLog,game.s.log)){const event=entry.event||{kind:entry.type,title:"Council report",text:entry.text};battleMessages.enqueue({text:entry.text,event});}syncPlayback();}if(game.s.battle&&game.battleHuman()&&!wasHuman)toast(`${name(game.ruler(game.battleOwner()))}: your army’s turn.`);if(!game.s.monthlyReview&&!game.s.battle&&game.isHuman()&&(game.s.player!==oldActor||oldBattle))handoff();}catch(e){game.s.paused=true;toast('AI paused: '+e.message);}}
 scheduleAI();},game.s.speed);}
function togglePause(){if(game.s.campaignEnded){toast('This campaign has ended. Start or load a campaign from Menu.');return;}game.s.paused=!game.s.paused;render();save();}
function handoff(){game.s.selected=game.ruler().home;navigate('turn');world?.overview();if(game.s.humanRulers.length<2){toast(`${name(game.ruler())}: your turn.`);return;}dialog('Pass the phone',`<p class="dialog-intro">Player ${game.s.humanRulers.indexOf(game.s.player)+1} · <b class="gold">${esc(name(game.ruler()))}</b> now controls the realm.</p>`,`<button id="acceptTurn" class="gold-button">I’m ready</button>`,'HOTSEAT');$('acceptTurn').onclick=close;}
function showLaunch(){if(provinceController?.guardClose())return;battleMessages.clear();presentedEvent=null;monthlyMessages.clear();monthlyKey='';replayMessages.clear();clearTimeout(aiTimer);audio?.stop();if(game){save();savedState=JSON.parse(JSON.stringify(game.s));}close();world?.destroy();world=null;toolController?.abort();$('game').hidden=true;$('cheatHud').hidden=true;$('launch').hidden=false;$('quitScreen').hidden=true;$('setupWizard').hidden=true;$('launchMenu').hidden=false;monthlyMessages.clear();monthlyKey='';}

let toolController;function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;toolController?.abort();toolController=new AbortController();const schema={type:'object',properties:{province:{type:'integer',minimum:1,maximum:41}},required:['province'],additionalProperties:false};const tools=[{name:'read_rtk2_campaign',title:'Read campaign',description:'Read the current date, ruler, and province resources without changing the campaign.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('No input fields are accepted.');return {year:game.s.year,month:game.s.month,ruler:game.ruler().name,humanRulers:game.s.humanRulers,ai:game.aiFor(),battle:game.s.battle?{target:game.s.battle.target,side:game.s.battle.side,day:game.s.battle.day}:null,selected:game.s.selected,provinces:game.s.provinces.map(p=>({id:p.id,name:p.name,owner:p.owner,gold:p.gold,food:p.food,land:p.land,flood:p.flood,loyalty:p.loyalty}))};}},{name:'select_rtk2_province',title:'Select province',description:'Navigate to a province on the map. This does not issue an order.',inputSchema:schema,annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='province')||!Number.isInteger(input.province))throw Error('A province number is required.');if(!setSelected(input.province))throw Error('Finish the current reassignment or battle before changing provinces.');return {selected:game.s.selected};}},{name:'stage_rtk2_order',title:'Prepare domestic order',description:'Open a domestic order form for review. This does not spend resources or complete an order.',inputSchema:{type:'object',properties:{province:{type:'integer',minimum:1,maximum:41},order:{type:'string',enum:Object.keys(commands)}},required:['province','order'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['province','order'].includes(k))||!Number.isInteger(input.province)||!Object.keys(commands).includes(input.order))throw Error('Provide a valid province and domestic order.');if(!game.isHuman()||game.s.battle||game.s.monthlyReview)throw Error('Wait for a human faction’s province-order turn.');if(provinceController?.isAllocating())throw Error('Finish troop reassignment before opening another order.');game.owned(input.province);if(!setSelected(input.province))throw Error('Finish the current order before changing provinces.');orderDialog(input.order);return {staged:input.order,province:game.s.selected};}}];for(const t of tools)try{Promise.resolve(context.registerTool(t,{signal:toolController.signal})).catch(()=>{});}catch{} }
async function loadYaml(){for(const path of ['../lib/js-yaml.js']){try{await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=path;script.onload=resolve;script.onerror=()=>{script.remove();reject(Error('Unavailable'));};document.head.append(script);});if(!globalThis.jsyaml?.load)continue;const res=await fetch('./config/game-config.yaml');if(!res.ok)throw Error('Missing config');const config=jsyaml.load(await res.text());const parsed={...DEFAULT_RULES};for(const key of Object.keys(DEFAULT_RULES)){const v=config?.[key];if(typeof v==='number'&&Number.isFinite(v)&&v>=0&&(key==='floodChance'||key==='populationGrowth'?v<=1:v>=1))parsed[key]=v;}librarySources.yaml=path;return parsed;}catch{}}return DEFAULT_RULES;}
async function init(){try{const [response,yaml,geo,terrain,art,aiResponse]=await Promise.all([fetch('./config/scenarios.json'),loadYaml(),fetch('./config/china-map.json'),fetch('./config/province-terrain.json'),loadRasterAssets(),fetch('./config/ai-config.json')]);if(!response.ok||!geo.ok||!terrain.ok)throw Error('Campaign data could not load.');scenarios=await response.json();chinaMap=await geo.json();terrains=await terrain.json();assets=art;artwork=createArtwork(assets);rules={...yaml,ai:validateAIConfig(await aiResponse.json())};audio=new AudioBus();audio.notice=toast;librarySources.graphics='Canvas 2D raster';try{const saved=localStorage.getItem(KEY);if(saved)savedState=validateSave(JSON.parse(saved),scenarios,terrains);}catch{savedState=null;}setupLaunch();artwork.refresh();$('loading').hidden=true;showLaunch();for(const [id,fn]of [['menu',settings],['provincePicker',provinceDialog],['closeDialog',close],['rotateFull',fullscreen],['cheatToggle',toggleHUD],['closeHud',toggleHUD],['battleHUD',toggleHUD],['battleMenu',settings],['portraitButton',()=>{const o=frameOfficer();if(o)officerDialog(o.id);}],['expandEvent',eventDialog]])$(id).onclick=fn;$('mapHome').onclick=()=>world.overview();$('zoomIn').onclick=()=>world.zoom(.8);$('zoomOut').onclick=()=>world.zoom(1.25);$('numbersToggle').onclick=()=>{game.s.settings.showNumbers=game.s.settings.showNumbers===false;render();save();};$('mapMode').onclick=()=>{if(game.s.battle){toast('The battle uses this province map.');return;}view=view==='china'?'province':'china';buildWorld();render();};$('ownershipToggle').onclick=()=>{game.s.settings.ownership=game.s.settings.ownership===false;render();save();};document.querySelectorAll('[data-hud]').forEach(b=>b.onclick=()=>{hudTab=b.dataset.hud;renderHUD();});window.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(!$('game').hidden)showLaunch();else if(!$('setupWizard').hidden){$('setupWizard').hidden=true;$('launchMenu').hidden=false;close();}else close();}});$('dialog').addEventListener('cancel',e=>{e.preventDefault();if(!$('game').hidden)showLaunch();else close();});window.addEventListener('pagehide',()=>{save();audio.stop();});window.rtk2={get state(){return game?.s;},get diagnostics(){return {...world?.stats,libraries:librarySources,audio:{sound:audio.sound,music:audio.music,playing:!audio.track.paused}};}};}catch(e){$('loadStatus').textContent=e.message;$('retry').hidden=false;$('retry').onclick=()=>location.reload();}}
