const scenarioTitles=['189 · A fractured Han','194 · Rival lords rise','201 · After Guandu','208 · Before Red Cliffs','215 · Three powers contend','220 · The Three Kingdoms'];
const scenarioStories=['The coalition gathers against Dong Zhuo. Fifteen realms vie for the Han lands.','Lords consolidate their holdings as ambition spreads across China.','Cao Cao has defeated Yuan Shao; the balance of power shifts north.','Cao Cao marches south. Liu Bei and Sun Quan face a decisive choice.','Wei, Shu, and Wu consolidate their borders amid rival claims.','The Han has fallen. A new dynasty rises while rival realms endure.'];
let setup={step:'scenario',scenario:0,count:1,humans:[],humanIndex:0,ai:1,familyMode:'expanded'};
function setupLaunch(){$('newGame').onclick=()=>{setup={step:'scenario',scenario:0,count:1,humans:[],humanIndex:0,ai:1,familyMode:'expanded'};$('launchMenu').hidden=true;$('setupWizard').hidden=false;renderSetup();};$('loadGame').onclick=()=>{importSave();};$('quitGame').onclick=()=>{audio.stop();clearTimeout(aiTimer);$('launch').hidden=true;$('quitScreen').hidden=false;window.close();};$('returnLaunch').onclick=showLaunch;$('cancelSetup').onclick=()=>{$('setupWizard').hidden=true;$('launchMenu').hidden=false;};$('wizardBack').onclick=setupBack;$('wizardNext').onclick=setupNext;}
function renderSetup(){const s=setupScenario(),rulers=s.rulers.filter(r=>s.provinces.some(p=>p.owner===r.id)),max=Math.min(12,rulers.length);$('launchError').textContent='';$('wizardNext').textContent=setup.step==='ai'?'Start Game':'Next';$('wizardStep').textContent=({scenario:'1 · SCENARIO',players:'2 · PLAYERS',rulers:'3 · RULER',ai:'4 · AI INTELLIGENCE'})[setup.step];
 if(setup.step==='scenario'){$('wizardTitle').textContent='Choose a scenario';$('wizardBody').innerHTML='<div class="scenario-grid">'+scenarios.map((s,i)=>`<button class="choice ${i===setup.scenario?'selected':''}" data-scenario="${i}" aria-pressed="${i===setup.scenario}"><span><strong>${scenarioTitles[i]}</strong><small>${scenarioStories[i]}</small></span></button>`).join('')+`</div><div class="suborder-grid"><button type="button" data-history="historic" aria-pressed="${setup.historyMode!=='fiction'}" class="${setup.historyMode!=='fiction'?'selected':''}">Historic</button><button type="button" data-history="fiction" aria-pressed="${setup.historyMode==='fiction'}" class="${setup.historyMode==='fiction'?'selected':''}">Fiction</button></div><p class="wizard-info">Historic includes recorded history and early-death windows. Fiction leaves lifespans to age and campaign events.</p><div class="section-label">FAMILY RULES</div><div class="suborder-grid"><button type="button" data-family="original" aria-pressed="${setup.familyMode==='original'}">Original</button><button type="button" data-family="expanded" aria-pressed="${setup.familyMode!=='original'}">Expanded</button></div><p class="wizard-info">Original has one marriage daughter. Expanded tracks spouses, princes and princesses, births and marriage from age 16.</p>`;document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{setup.familyMode=b.dataset.family;renderSetup();});document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{setup.historyMode=b.dataset.history;renderSetup();});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{setup.scenario=Number(b.dataset.scenario);setup.custom=null;setup.humans=[];renderSetup();});}
 if(setup.step==='players'){$('wizardTitle').textContent='How many human players?';$('wizardBody').innerHTML=`<p class="wizard-info">0 runs AI against AI. This scenario has ${rulers.length} active rulers and supports up to ${max} humans.</p><div class="player-grid">${Array.from({length:13},(_,i)=>`<button data-count="${i}" class="player-count ${i===setup.count?'selected':''}" aria-pressed="${i===setup.count}" ${i>max?'disabled':''}>${i}</button>`).join('')}</div><p class="wizard-info">${setup.count===0?'Spectator mode. Esc returns to launch.':`${setup.count} human ${setup.count===1?'player':'players'} will share this phone.`}</p>`;document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{setup.count=Number(b.dataset.count);setup.humans=setup.humans.slice(0,setup.count);renderSetup();});}
 if(setup.step==='rulers'){$('wizardTitle').textContent=`Choose ruler · Player ${setup.humanIndex+1} of ${setup.count}`;$('wizardBody').innerHTML='<div class="ruler-grid">'+rulers.map(r=>{const chosen=setup.humans[setup.humanIndex]===r.id,taken=setup.humans.some((id,i)=>i!==setup.humanIndex&&id===r.id);return `<button class="choice ${chosen?'selected':''}" data-ruler="${r.id}" aria-pressed="${chosen}" ${taken?'disabled':''}>${portraitMarkup(s.officers[r.leader],'portrait-mini')}<span><strong>${esc(r.name)} · ${esc(r.zh)}</strong><small>${s.provinces.filter(p=>p.owner===r.id).length} provinces${taken?' · Already selected':''}</small></span></button>`;}).join('')+'</div>';document.querySelectorAll('[data-ruler]').forEach(b=>b.onclick=()=>{setup.humans[setup.humanIndex]=Number(b.dataset.ruler);renderSetup();});const add=document.createElement('button');add.id='createCustomRuler';add.textContent=setup.custom?'Edit custom ruler':'Create custom ruler';add.onclick=customRulerDialog;$('wizardBody').prepend(add);artwork?.refresh();}
 if(setup.step==='ai'){$('wizardTitle').textContent='Choose AI intelligence';$('wizardBody').innerHTML='<div class="ai-choices">'+[['Beginner','Simple choices and cautious expansion'],['Medium','Balanced economy and military priorities'],['Hard','Strong commanders, deliberate movement and aggressive expansion']].map(([name,desc],i)=>`<button data-level="${i}" class="choice ${setup.ai===i?'selected':''}" aria-pressed="${setup.ai===i}"><span><strong>${name}</strong><small>${desc}</small></span></button>`).join('')+'</div>';document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{setup.ai=Number(b.dataset.level);renderSetup();});}
}
function setupBack(){if(setup.step==='scenario'){$('setupWizard').hidden=true;$('launchMenu').hidden=false;return;}if(setup.step==='players')setup.step='scenario';else if(setup.step==='rulers'){if(setup.humanIndex>0)setup.humanIndex--;else setup.step='players';}else {setup.step=setup.count===0?'players':'rulers';setup.humanIndex=setup.count-1;}renderSetup();}
function setupNext(){try{if(setup.step==='scenario'){setup.step='players';const max=Math.min(12,setupScenario().rulers.filter(r=>setupScenario().provinces.some(p=>p.owner===r.id)).length);setup.count=Math.min(setup.count,max);}else if(setup.step==='players'){setup.step=setup.count===0?'ai':'rulers';setup.humanIndex=0;}else if(setup.step==='rulers'){if(!Number.isInteger(setup.humans[setup.humanIndex]))throw Error('Select this player’s ruler.');if(setup.humanIndex+1<setup.count)setup.humanIndex++;else setup.step='ai';}else {const state=createCampaign(setupScenario(),setup.count===0?[]:setup.humans,setup.ai+1);state.historyMode=setup.historyMode||'historic';state.familyMode=setup.familyMode||'expanded';state.ai={intelligence:[25,60,90][setup.ai],aggression:[35,55,75][setup.ai]};state.aiLevel=['beginner','medium','hard'][setup.ai];try{const p=JSON.parse(localStorage.getItem('rtk2-audio-preferences')||'null');if(p)Object.assign(state.settings,{sound:p.sound!==false,music:p.music!==false});}catch{}start(state);return;}renderSetup();}catch(e){$('launchError').textContent=e.message;}}

