 const root=battleMenu==='orders',pending=battleMode==='reinforcePlace'&&pendingReinforce;
 $('panelBody').innerHTML=`${pending?'<p class="battle-notice">Choose an entry hex</p><button id="cancelReinforcement">Cancel reinforcement</button>':`<div class="battle-actions ${root?'primary-battle':'battle-submenu'}">${buttons.map(([id,label])=>`<button ${root?'data-battle':battleMenu==='strategy'?'data-strategy':'data-tactic'}="${id}" class="${!root&&battleMode===id?'active ':''}${battleOrderUnavailable(b,u,id)?'order-unavailable':''}" ${human?'':'disabled'}>${label}</button>`).join('')}</div>`}`+'<div class="battle-turn-controls">'+(root?'':'<button id="battleBack" aria-label="Back to orders">Back</button>')+'<button id="battleEndTurn" class="gold-button" '+(human?'':'disabled')+'>End turn</button></div>';
