function armyColumn(side){
 const b=game.s.battle,info=armySummary(game,b,side),label=side==='defend'?'Defender':'Attacker';
 const values=[['men',compact(info.men),num(info.men)+' soldiers'],['generals',info.generals+'/'+info.remaining,info.generals+' in the field / '+info.remaining+' remaining in '+info.province.name],['food',compact(info.food),num(info.food)+' rice'],['gold',compact(info.gold),num(info.gold)+' gold'],['weapons',compact(info.weapons),num(info.weapons)+' weapons · '+info.armedPercent+'% of soldiers armed']];
 return `<div class="army-column ${side} ${controllerSide(b)===side?'active-army':''}" data-side="${side}"><div class="army-heading"><small>${label}</small><strong title="${esc(name(info.ruler))}">${esc(name(info.ruler))}</strong></div><button class="army-picture" data-army-leader="${info.leader?.id??''}" aria-label="Inspect ${esc(info.leader?name(info.leader):label)}" title="${side===b.side?'Free inspection':'Enemy inspection · 100 gold'}" ${!game.battleHuman()||!info.leader||b.challenge?'disabled':''}>${portraitMarkup(info.leader,'battle-portrait')}</button><strong class="army-leader" title="${esc(info.leader?name(info.leader):'No commander')}">${esc(info.leader?name(info.leader):'—')}</strong>${values.map(([key,value,title])=>`<span data-army-stat="${key}" title="${esc(title)}" aria-label="${esc(title)}">${value}</span>`).join('')}</div>`;
}
function renderArmyComparison(){
 const b=game.s.battle,root=$('battleComparison');
 if(!root.querySelector('[data-side]'))root.innerHTML=armyColumn('defend')+'<div class="army-column army-labels"><div></div><div class="army-picture"><canvas id="battleWeatherImage" data-atlas="weather" role="img"></canvas></div><div></div><span>Men</span><span>Generals</span><span>Food</span><span>Gold</span><span>Weapons</span></div>'+armyColumn('attack');
 for(const side of ['defend','attack']){
  const info=armySummary(game,b,side),column=root.querySelector(`[data-side="${side}"]`),ruler=column.querySelector('.army-heading strong'),leader=column.querySelector('.army-leader'),picture=column.querySelector('.army-picture'),label=side==='defend'?'Defender':'Attacker';
  column.classList.toggle('active-army',controllerSide(b)===side);ruler.textContent=name(info.ruler);ruler.title=name(info.ruler);leader.textContent=info.leader?name(info.leader):'—';leader.title=info.leader?name(info.leader):'No commander';
  picture.dataset.armyLeader=info.leader?.id??'';picture.disabled=!game.battleHuman()||!info.leader||!!b.challenge;picture.setAttribute('aria-label','Inspect '+(info.leader?name(info.leader):label));picture.title=side===b.side?'Free inspection':'Enemy inspection · 100 gold';picture.onclick=()=>battleInspect(Number(picture.dataset.armyLeader));
  const portraitKey=String(info.leader?.id)+':'+game.s.year;if(picture.dataset.portraitKey!==portraitKey){picture.dataset.portraitKey=portraitKey;picture.innerHTML=portraitMarkup(info.leader,'battle-portrait');}
  const values=[['men',compact(info.men),num(info.men)+' soldiers'],['generals',info.generals+'/'+info.remaining,info.generals+' in the field / '+info.remaining+' remaining in '+info.province.name],['food',compact(info.food),num(info.food)+' rice'],['gold',compact(info.gold),num(info.gold)+' gold'],['weapons',compact(info.weapons),num(info.weapons)+' weapons · '+info.armedPercent+'% of soldiers armed']];
  for(const [key,value,title]of values){const cell=column.querySelector(`[data-army-stat="${key}"]`);cell.textContent=value;cell.title=title;cell.setAttribute('aria-label',title);}
 }
 const weather=$('battleWeatherImage');weather.dataset.cell=({sunny:0,fewclouds:1,cloudy:2,rain:3})[b.weather];weather.setAttribute('aria-label',WEATHER[b.weather]);root.scrollTop=0;
}
function battleControlsDialog(){
 const b=game.s.battle,army=living(b).filter(u=>u.side===b.side),u=army.find(v=>v.id===b.selected),human=game.battleHuman();
 const directions=b.phase!=='deployment'&&battleMode==='move'&&u?`<div class="direction-pad" aria-label="Six hex movement directions">${[0,1,2,-1,3,4,5].map(i=>{const d=DIRECTIONS[i],cell=i<0?null:direction(u.q,u.r,i),valid=i<0||reachable(b,u).some(p=>p.q===cell.q&&p.r===cell.r);return `<button data-direction="${i}" ${human&&!u.ordered&&valid?'':'disabled'} aria-label="${i<0?'Wait':d.label}">${i<0?'Wait':d.arrow}</button>`;}).join('')}</div>`:'';
 dialog('Battle controls',`${selectField('battleUnit','Unit',options(army.map(v=>[v.id,game.officer(v.id).name+' · '+(v.ordered?'Done':v.mobility+' MP')]),b.selected))}<p class="dialog-intro">${b.phase==='deployment'?(b.side==='attack'?`Enter from the ${DIRECTIONS[b.entryDirection].label.toLowerCase()} edge facing ${game.province(b.source).name}.`:'Place defenders on highlighted passable ground.'):'Current action: '+battleMode+'. You can tap a target directly on the battlefield.'}</p>${directions}<div class="form-grid">${numberField('hexQ','Column',1,13,u?.placed?u.q+1:1)}${numberField('hexR','Row',1,12,u?.placed?u.r+1:1)}</div><button id="targetHex" ${human?'':'disabled'}>Use selected action</button>${b.phase!=='deployment'?`<div class="dialog-buttons"><button id="endBattleSide" ${human&&!b.challenge?'':'disabled'}>Finish army orders</button>${b.day===1&&u?.war>=b.challengeWar&&b.challengeIssued.length===0?`<button id="personalChallenge" ${human&&!u.ordered?'':'disabled'}>Personal challenge</button>`:''}</div>`:''}<div class="section-label">BATTLE LOG</div><div class="battle-log">${b.events.slice(0,8).map(t=>`<p>${esc(t)}</p>`).join('')}</div>`,`<button id="closeBattleControls">Return to battle</button>`,'BATTLE');
 $('closeBattleControls').onclick=close;$('battleUnit').disabled=!human;$('battleUnit').onchange=()=>{b.selected=Number($('battleUnit').value);battleMenu='orders';refresh();battleControlsDialog();};$('targetHex').onclick=()=>{const q=Number($('hexQ').value)-1,r=Number($('hexR').value)-1;close();onHex(q,r);};
 $('dialogBody').querySelectorAll('[data-direction]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.direction),cell=i<0?null:direction(u.q,u.r,i);close();if(i<0)battleOrder('wait',{unit:u.id});else onHex(cell.q,cell.r);});
 $('endBattleSide')?.addEventListener('click',()=>{close();battleOrder('end');});$('personalChallenge')?.addEventListener('click',challengeDialog);
}
function viewUnitPicker(){const b=game.s.battle;dialog('View a battlefield unit',`${selectField('inspectTarget','Unit',options(b.units.filter(u=>visibleUnit(b,u)).map(u=>[u.id,`${game.officer(u.id).name} · ${u.side===b.side?'Friendly · Free':'Enemy · 100 gold'}`])))}<p class="dialog-intro">Inspection does not use a daily order. Each enemy inspection costs 100 gold.</p>`,`<button id="cancelInspect">Cancel</button><button id="inspectUnit" class="gold-button">View unit</button>`,'BATTLE VIEW');$('cancelInspect').onclick=close;$('inspectUnit').onclick=()=>battleInspect(Number($('inspectTarget').value));}
function battleInspect(id){try{const b=game.s.battle,serial=b?.eventSerial||0,u=b?.units.find(u=>u.id===id);if(!u)throw Error('Choose a unit on the battlefield.');if(!game.battleHuman())throw Error('The current army is controlled by AI.');game.battleAction('view',{target:id});const o=game.officer(id);refresh();showBattleMessages(b,serial);dialog(name(o),`${portraitMarkup(o,'dialog-portrait')}<p class="dialog-intro">${u.side===b.side?'Friendly':'Enemy'} general · ${u.placed?'Hex '+(u.q+1)+','+(u.r+1):'Awaiting placement'}</p><div class="form-grid">${[['War',u.war],['Intelligence',u.int],['Loyalty',o.loyalty],['Soldiers',num(u.soldiers)],['Morale',u.morale],['Mobility',u.mobility],['Training',u.training],['Weapons',num(u.weapons)],['Armed soldiers',Math.floor(100*Math.min(u.weapons,u.soldiers)/Math.max(1,u.soldiers))+'%']].map(([label,value])=>`<div class="metric-row"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`,`<button id="officerClose">Close</button>`,'UNIT INSPECTION');$('officerClose').onclick=close;}catch(e){toast(e.message);}}
function fleeUnit(){const b=game.s.battle,u=b.units.find(u=>u.id===b.selected);if(!u)return;if(isLeader(b,u)){dialog('Accept defeat and withdraw?',`<p class="dialog-intro">${esc(game.officer(u.id).name)} is the lead general. Confirming this flight withdraws every unit and concedes defeat.</p>`,`<button id="stayBattle">Stay</button><button id="confirmRetreat" class="gold-button">Confirm defeat</button>`,'COMMANDER’S FLIGHT');$('stayBattle').onclick=close;$('confirmRetreat').onclick=()=>{close();battleOrder('flee',{unit:u.id,confirmArmy:true});};return;}const choices=retreatOptions(game,u);dialog('Choose a retreat province',`<p class="dialog-intro">${esc(game.officer(u.id).name)} will leave the battlefield with this unit.</p>${choices.length?selectField('retreatProvince','Province',options(choices.map(p=>provinceChoice(game,p)))):'<p>No unoccupied connected province is available.</p>'}`,`<button id="stayBattle">Stay</button><button id="confirmUnitRetreat" class="gold-button" ${choices.length?'':'disabled'}>Retreat</button>`,'GENERAL’S FLIGHT');$('stayBattle').onclick=close;$('confirmUnitRetreat').onclick=()=>{const province=Number($('retreatProvince').value);close();battleOrder('flee',{unit:u.id,province});};}
function challengeDialog(){const b=game.s.battle;dialog('Call a personal challenge',`${selectField('challengeTarget','Opposing general',options(living(b).filter(u=>u.side!==b.side&&visibleUnit(b,u)).map(u=>[u.id,game.officer(u.id).name])))}<p class="dialog-intro">Day 1 only; war ${b.challengeWar} or higher. Accepting risks capture of the losing general. Refusal costs 5% of the opposing army’s soldiers.</p>`,`<button id="cancelChallenge">Cancel</button><button id="issueChallenge" class="gold-button">Issue challenge</button>`,'PERSONAL COMBAT');$('cancelChallenge').onclick=close;$('issueChallenge').onclick=()=>{const target=Number($('challengeTarget').value);close();battleOrder('challenge',{unit:b.selected,target});};}

function reinforceDialog(){const b=game.s.battle,opts=reinforcementOptions(game);dialog('Call reinforcements',`${selectField('reinforceOfficer','Reserve commander',options(opts.map(o=>[o.province+':'+o.officer,`${game.officer(o.officer).name} · ${provinceOwnerLabel(game,game.province(o.province))} · ${num(o.soldiers)} soldiers`])))}${numberField('reinforceFood','Rice to bring',0,opts[0]?.food??0,Math.min(5000,opts[0]?.food??0))}<p class="dialog-intro">Reserve commanders must be ready. An officer stays behind to govern. You will choose the entry hex next.</p>`,`<button id="cancelReinforce">Cancel</button><button id="askAlliedSupport">Ask ally</button><button id="chooseReinforceHex" class="gold-button" ${opts.length?'':'disabled'}>Choose entry hex</button>`,'REINFORCEMENT');$('cancelReinforce').onclick=close;$('askAlliedSupport').onclick=()=>{const b=game.s.battle,r=game.ruler(b.side==='attack'?b.attacker:b.defender),enemy=b.side==='attack'?b.defender:b.attacker,allies=r.alliances.filter(id=>!game.ruler(id).alliances.includes(enemy)&&!b.supportAsked?.includes(id));dialog('Request allied help',selectField('supportAlly','Ask which ruler?',options(allies.map(id=>[id,game.ruler(id).name])))+'<p id="supportError" class="form-error"></p>','<button id="cancelSupport">Cancel</button><button id="requestSupport" class="gold-button">Send messenger</button>','ALLIED SUPPORT');$('cancelSupport').onclick=close;$('requestSupport').disabled=!allies.length;$('requestSupport').onclick=()=>{try{game.requestBattleAlly(Number($('supportAlly').value));$('dialog').close();refresh();}catch(e){$('supportError').textContent=e.message;}};};$('reinforceOfficer').onchange=()=>{const [province,officer]=$('reinforceOfficer').value.split(':').map(Number),opt=opts.find(o=>o.province===province&&o.officer===officer);$('reinforceFood').max=opt.food;$('reinforceFood').value=Math.min(5000,opt.food);};$('chooseReinforceHex').onclick=()=>{const [province,officer]=$('reinforceOfficer').value.split(':').map(Number);pendingReinforce={province,officer,food:Number($('reinforceFood').value)};battleMode='reinforcePlace';battleMenu='orders';close();render();world.update();};}
function bribeDialog(){const b=game.s.battle,enemies=living(b).filter(u=>u.side!==b.side&&u.id!==b.rulers[u.side]&&visibleUnit(b,u)),bank={gold:b.gold[b.side]};dialog('Bribe an enemy general',`${selectField('bribeTarget','Enemy general',options(enemies.map(u=>[u.id,game.officer(u.id).name])))}${numberField('bribeGold','Gold offered',100,Math.max(100,bank.gold),Math.min(1000,Math.max(100,bank.gold)))}<p class="dialog-intro">Intelligence, loyalty and the offer affect success. Gold is spent even when the general refuses. Rulers cannot be bribed.</p>`,`<button id="cancelBribe">Cancel</button><button id="offerBribe" class="gold-button" ${enemies.length&&bank.gold>=100&&b.selected===b.leaders[b.side]?'':'disabled'}>Offer bribe</button>`,'BRIBERY');$('cancelBribe').onclick=close;$('offerBribe').onclick=()=>{const target=Number($('bribeTarget').value),gold=Number($('bribeGold').value);close();battleOrder('bribe',{unit:b.selected,target,gold});};}

function invadeDialog(){const p=selected(),targets=p.neighbors.map(id=>game.province(id)).filter(q=>![255,p.owner].includes(q.owner));dialog('Prepare an invasion',`<p class="dialog-intro">Select 1–10 ready commanders with troops. Leave at least one officer to govern. Army rice is deducted now; unused rice returns after battle. Allied realms need the alliance broken first.</p><form id="invasionForm">${selectField('enemyProvince','Enemy province',options(targets.map(q=>[q.id,`${provinceOwnerLabel(game,q)}${game.ruler().alliances.includes(q.owner)?' · Allied':''}`,{province:q.id}])))}<div class="commander-list">${p.officers.map(id=>{const o=game.officer(id);return `<label><input type="checkbox" name="commander" value="${id}" ${o.acted||o.sick||o.injured||!o.soldiers?'disabled':''}> <span>${esc(o.name)}<small>INT ${o.int} · WAR ${o.war} · CHA ${o.charm} · ${num(o.soldiers)} men · TRAIN ${o.training} · WEAPONS ${num(o.weapons)}${o.sick||o.injured?' · Recovering':o.acted?' · Acted':''}</small></span></label>`;}).join('')}</div>${numberField('armyRice','Army rice',1,p.food,Math.min(p.food,20000))}${numberField('armyGold','Army gold',0,p.gold,Math.min(p.gold,1000))}<aside id="warProvisions" class="advisor-insight" role="status" aria-live="polite"></aside><div id="warAdvisor"></div><section id="warGovernor" hidden><div id="warGovernorChoices"></div><div id="warGovernorAdvice" role="status"></div></section></form><p id="warError" class="form-error" role="alert"></p>`,`<button id="cancelInvasion">Cancel</button><button id="breakAlliance">Break alliance</button><button id="launchInvasion" class="gold-button" ${targets.length?'':'disabled'}>March</button>`,'WAR COUNCIL');let governorKey='';const estimate=()=>{const ids=[...$('invasionForm').querySelectorAll('input[name=commander]:checked')].map(n=>Number(n.value)),men=ids.reduce((n,id)=>n+game.officer(id).soldiers,0),e=warProvisions(men,Number($('armyRice').value));$('warProvisions').innerHTML=men?`<strong>${num(men)} soldiers · ${num(ids.reduce((total,id)=>total+game.officer(id).weapons,0))} weapons · food estimate</strong><span>${num(e.daily)} rice / day · approximately ${num(e.monthly)} rice / 30-day month.</span><span class="${e.days<30?'negative':''}">Supplies cover about ${e.days} days at full strength. Losses reduce consumption; reinforcements increase it.</span>`:'<span>Select commanders to estimate monthly food.</span>';$('warAdvisor').innerHTML=ids.length?orderInsight(game,'War invasion',ids[0],{officers:ids,target:Number($('enemyProvince').value),food:Number($('armyRice').value)}):'';const needs=ids.includes(p.governor),remaining=p.officers.filter(id=>!ids.includes(id)),key=needs?remaining.join(','):'';$('warGovernor').hidden=!needs;if(key!==governorKey){governorKey=key;$('warGovernorChoices').innerHTML=needs?selectField('warGovernorSelect','Who will govern Province #'+p.id+'?',options([['','Choose a governor'],...remaining.map(id=>[id,game.officer(id).name])])):'';if(needs){$('warGovernorSelect').dataset.purpose='Appoint governor';enhanceControls($('warGovernorChoices'),game);const advise=()=>{const value=$('warGovernorSelect').value;$('warGovernorAdvice').innerHTML=value===''?'Select a candidate to hear the advisor’s assessment.':orderInsight(game,'Appoint governor',Number(value))||'<p class="notice">No qualified advisor is here. Review loyalty and abilities on the candidate’s card; low loyalty increases the risk of enemy persuasion.</p>';artwork.refresh();};$('warGovernorSelect').onchange=advise;advise();}}};$('invasionForm').addEventListener('input',estimate);$('invasionForm').addEventListener('change',estimate);estimate();$('cancelInvasion').onclick=close;$('breakAlliance').onclick=()=>{try{const id=game.province($('enemyProvince').value).owner;game.execute('diplomaticMission',{province:p.id,mode:'cancel',target:id});save();$('warError').textContent='Alliance cancelled. You can now march.';}catch(e){$('warError').textContent=e.message;}};$('launchInvasion').onclick=()=>{try{game.execute('attack',{province:p.id,target:Number($('enemyProvince').value),officers:[...$('invasionForm').querySelectorAll('input[name=commander]:checked')].map(n=>Number(n.value)),food:Number($('armyRice').value),gold:Number($('armyGold').value),governor:$('warGovernorSelect')?.value===''?undefined:$('warGovernorSelect')?.value});close();battleMode='move';if(game.battleDetailed()){$('game').classList.add('battle-active');battleMenu='orders';view='province';buildWorld();}refresh();if(!game.s.battle)toast(game.s.lastEvent.text);}catch(e){$('warError').textContent=e.message;}};}
function onHex(q,r){const b=game.s.battle;if(!b){if(pendingFort){try{game.execute('buildFort',{province:pendingFort.province,officer:pendingFort.officer,q,r});pendingFort=null;refresh();toast('Fort constructed.');}catch(e){toast(e.message);}return;}if(Number.isInteger(q)&&Number.isInteger(r)&&q>=0&&q<13&&r>=0&&r<12)toast(`Hex ${q+1},${r+1} · ${TERRAIN[provinceTerrain(selected(),terrains[selected().id-1])[r*13+q]]||'Outside battlefield'}`);return;}if(!game.battleHuman()){toast('Pause and use HUD to inspect an AI battle.');return;}if(b.challenge){toast('Answer the personal challenge first.');return;}if(b.phase==='deployment'){battleOrder('place',{unit:b.selected,q,r});return;}const actual=at(b,q,r),v=actual&&visibleUnit(b,actual)?actual:null;if(battleMode==='view'){if(v)battleInspect(v.id);else toast('Choose a unit to view.');return;}if(battleMode==='reinforcePlace'&&pendingReinforce){const before=b;const success=battleOrder('reinforce',{unit:b.selected,...pendingReinforce,q,r});if(success){pendingReinforce=null;game.battlePlacementSide=null;battleMode='move';if(game.s.battle===before){render();world.update();}}return;}if(v&&v.side===b.side&&battleMode!=='fireball'){b.selected=v.id;battleMenu='orders';refresh();return;}const args={unit:b.selected,q,r};if(['attack','charge','simultaneous','moveEnemy'].includes(battleMode))args.target=v?.id;battleOrder(battleMode,args);}
function battleOrder(action,args={}){try{battleMenu='orders';const before=game.s.battle,serial=before?.eventSerial||0,previousOwner=game.battleOwner();if(!game.battleHuman())throw Error('The current army is controlled by AI.');const message=game.battleAction(action,args);audio.play(['fire','fireball'].includes(action)?'fire':['attack','charge','simultaneous','challenge','challengeResponse'].includes(action)?'battle':'order');refresh();showBattleMessages(before,serial);if(!game.s.battle&&before?.suspended){}else if(!game.s.battle&&before)toast(`${game.ruler(game.s.lastBattle.winner==='attack'?before.attacker:before.defender).name} won at ${selected().name}. ${game.s.lastBattle.reason}`);else{if(game.battleHuman()&&game.s.humanRulers.length>1&&previousOwner!==game.battleOwner()){const id=game.battleOwner();dialog('Pass the phone',`<p class="dialog-intro">Player ${game.s.humanRulers.indexOf(id)+1} · ${esc(name(game.ruler(id)))} controls this army.</p>`,`<button id="acceptArmy" class="gold-button">I’m ready</button>`,'BATTLE HOTSEAT');$('acceptArmy').onclick=close;}}return true;}catch(e){toast(e.message);return false;}}

function numberField(id,label,min,max,value){return `<div class="field"><label for="${id}">${label} (${min}–${max})</label><input id="${id}" name="${id}" type="range" min="${min}" max="${max}" step="1" value="${value}"></div>`;}
let hudEntities={ai:'global',officer:0,province:9,battle:null};
function toggleHUD(){const open=$('cheatHud').hidden;$('cheatHud').hidden=!open;if(open){game.s.paused=true;hudEntities.province=game.s.selected;hudEntities.officer=selected().officers[0]??0;renderHUD();render();save();}}
function renderHUD(){document.querySelectorAll('[data-hud]').forEach(b=>b.classList.toggle('active',b.dataset.hud===hudTab));$('hudError').textContent='';const kind=hudTab;let opts=[],entity,fields=[];
 $('singleAIStep').onclick=()=>{try{if(!game.aiStep())throw Error('Waiting for a human faction or army.');refresh();renderHUD();}catch(e){$('hudError').textContent=e.message;}};$('resumeHud').onclick=()=>{$('cheatHud').hidden=true;game.s.paused=false;render();save();};
 if(kind==='ai'){opts=[['global','All AI defaults'],...game.s.rulers.map(r=>[r.id,r.name])];const id=hudEntities.ai;entity=id==='global'?game.s.ai:game.aiFor(Number(id));fields=[['intelligence',100],['aggression',100]];}
 if(kind==='officer'){opts=game.s.officers.filter(o=>o.name).map(o=>[o.id,`${o.name} · ${game.s.provinces.find(p=>['officers','unclaimed','hidden'].some(k=>p[k].includes(o.id)))?.name||'Unplaced'}`]);entity=game.officer(hudEntities.officer);fields=[['int',100],['war',100],['charm',100],['loyalty',100],['training',100],['soldiers',10000],['weapons',10000],['compatibility',255],['virtue',100],['ambition',100]];}
 if(kind==='province'){opts=game.s.provinces.map(p=>provinceChoice(game,p));entity=game.province(hudEntities.province);fields=[['gold',30000],['food',3000000],['population',3000000],['land',100],['flood',100],['loyalty',100],['castle',100],['horses',100],['ricePrice',120]];}
 if(kind==='battle'){const b=game.s.battle;if(!b){$('hudBody').innerHTML='<p class="dialog-intro">Start an invasion to edit the battlefield. AI is paused while HUD is open.</p>';return;}opts=b.units.map(u=>[u.id,`${game.officer(u.id).name} · ${u.side}`]);if(!b.units.some(u=>u.id===Number(hudEntities.battle)))hudEntities.battle=b.units[0].id;entity=b.units.find(u=>u.id===Number(hudEntities.battle));fields=[['soldiers',10000],['morale',100],['mobility',1000],['war',100],['int',100],['weapons',10000]];}
 const labels={int:'Intelligence',war:'War skill',charm:'Charm',food:'Rice',flood:'Dikes',land:'Land',ricePrice:'Rice per gold',mobility:'Mobility',compatibility:'Compatibility'};
 $('hudBody').innerHTML=`<p class="hud-note">AI paused · changes apply to the live campaign</p>${selectField('hudEntity','Edit',options(opts,hudEntities[kind]))}<form id="hudForm"><div class="form-grid">${fields.map(([k,max])=>numberField('hud_'+k,labels[k]||k[0].toUpperCase()+k.slice(1),k==='ricePrice'?1:0,max,entity[k]??0)).join('')}</div>${kind==='officer'?`<label class="check-label"><input type="checkbox" id="hudActed" ${entity.acted?'checked':''}> Already acted this month</label>`:''}${kind==='province'?`${selectField('hudOwner','Province ruler',options([[255,'Unclaimed'],...game.s.rulers.map(r=>[r.id,r.name])],entity.owner))}<label class="check-label"><input type="checkbox" id="hudMerchant" ${entity.merchant?'checked':''}> Merchant present</label><label class="check-label"><input type="checkbox" id="hudReset"> Reset this province’s monthly actions</label>`:''}${kind==='battle'?`<div class="form-grid">${numberField('hud_day','Battle day',1,30,game.s.battle.day)}${numberField('hud_challengeWar','Challenge war threshold',0,100,game.s.battle.challengeWar)}${selectField('hud_windStrength','Wind strength',options([[0,'Calm'],[1,'Breeze'],[2,'Strong'],[3,'Gale']],game.s.battle.windStrength))}${selectField('hud_wind','Wind direction',options([[0,'Calm'],...DIRECTIONS.map((d,i)=>[i+1,d.arrow+' '+d.label])],game.s.battle.wind))}${numberField('hud_attackFood','Invaders’ rice',0,3000000,game.s.battle.food.attack)}${numberField('hud_defendFood','Defenders’ rice',0,3000000,game.s.battle.food.defend)}</div>${selectField('hudWeather','Weather',options(Object.entries(WEATHER)))}<label class="check-label"><input type="checkbox" id="hudOrdered" ${entity.ordered?'checked':''}> Daily order already completed</label>`:''}<button id="applyHud" type="submit" class="gold-button">Apply changes</button></form><div class="section-label">EVENT ARTWORK PREVIEW</div><div class="dialog-buttons"><button data-preview="diplomacy">Diplomacy</button><button data-preview="prison">Messenger detained</button><button id="clearPreview">Live event</button></div>`;
 $('hudBody').querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{game.s.eventPreview={kind:b.dataset.preview,title:'Artwork preview · '+(b.dataset.preview==='prison'?'Messenger detained':'Diplomacy'),text:'Testing preview only. The campaign has not changed.'};renderFrames();});$('clearPreview').onclick=()=>{delete game.s.eventPreview;renderFrames();};if(kind==='battle')$('hudWeather').value=game.s.battle.weather;$('hudEntity').onchange=()=>{hudEntities[kind]=$('hudEntity').value;renderHUD();};$('hudForm').onsubmit=e=>{e.preventDefault();try{const values=Object.fromEntries(fields.map(([k])=>[k,Number($('hud_'+k).value)]));if(kind==='officer')values.acted=$('hudActed').checked;if(kind==='province')Object.assign(values,{owner:Number($('hudOwner').value),merchant:$('hudMerchant').checked,resetActions:$('hudReset').checked});if(kind==='battle')Object.assign(values,{ordered:$('hudOrdered').checked,day:Number($('hud_day').value),challengeWar:Number($('hud_challengeWar').value),windStrength:Number($('hud_windStrength').value),wind:Number($('hud_wind').value),attackFood:Number($('hud_attackFood').value),defendFood:Number($('hud_defendFood').value),weather:$('hudWeather').value});game.cheat(kind,hudEntities[kind],values);refresh();renderHUD();$('hudError').textContent='Applied.';}catch(e){$('hudError').textContent=e.message;}};
}
function portraitMarkup(o,className=''){const label=portraitAssigned(o)?`Artist portrait of ${o.name}`:`Reserved portrait for ${o?.name||'an officer'}`;return `<canvas class="portrait-image ${className}" data-atlas="${portraitFrame(o,game?.s.year).atlas}" data-cell="${portraitFrame(o,game?.s.year).cell}" role="img" aria-label="${esc(label)}"></canvas>`;}

function frameOfficer(){const p=selected();return p.governor===null?null:game.officer(p.governor);}
function renderFrames(){if(!game)return;const o=frameOfficer(),node=$('generalPortrait');node.dataset.atlas=portraitFrame(o,game?.s.year).atlas;node.dataset.cell=portraitFrame(o,game?.s.year).cell;node.setAttribute('aria-label',o?`${portraitAssigned(o)?'Artist portrait':'Reserved portrait'} of ${name(o)}`:'Reserved general portrait');$('portraitStatus').textContent=o&&!portraitAssigned(o)?'Portrait reserved':'';$('portraitButton').disabled=!o;const event=presentedEvent||eventFor(game);const frame=eventFrame(event);$('eventArtwork').dataset.atlas=frame.atlas;$('eventArtwork').dataset.cell=frame.cell;$('eventArtwork').setAttribute('aria-label',event.art?event.title:({diplomacy:'Diplomatic audience',prison:'Detained officers',war:'Military campaign'})[event.kind]||'Council scene');$('eventTitle').textContent=event.title;$('eventText').textContent=event.text;artwork?.refresh();}
function eventDialog(e=eventFor(game)){if(typeof e?.text!=='string')e=eventFor(game);const frame=eventFrame(e);replayMessages.clear();dialog(e.title,`<div class="event-full"><canvas class="event-image" data-atlas="${frame.atlas}" data-cell="${frame.cell}" role="img" aria-label="${esc(e.title)}"></canvas></div><p>${esc(e.text)}</p>`,'','EVENT');replayMessages.enqueue({onDone:close});syncPlayback();}


function royalFamilyDialog(id){
 const r=game.ruler(Number(id)),f=r.family,expanded=game.s.familyMode==='expanded',eligible=expanded?eligibleRoyalChildren(game.s,r):[];
 const rows=expanded&&f?f.children.map(c=>{const age=childAge(game.s,c);return `<article class="royal-child"><strong>${esc(c.name)}</strong><span>${c.sex==='female'?'Princess':'Prince'} · Age ${age}</span><span>${c.marriedTo!==null?'Married to '+esc(game.ruler(c.marriedTo)?.name||'a former ruler'):age>=16?'Available for royal marriage':`${16-age} ${16-age===1?'year':'years'} until eligible`}${c.nativeSlot?' · Original marriage slot':''}</span></article>`;}).join(''):'';
 const due=f?.pregnancy?.due;
 dialog(name(r)+' · Royal Family',expanded?`<p class="dialog-intro">Expanded family rules</p><div class="metric-row"><span>Spouse</span><strong>${f?.spouse?esc(f.spouse.name)+' · Age '+childAge(game.s,f.spouse):'Unmarried'}</strong></div><div class="metric-row"><span>Princes / Princesses</span><strong>${f?.children.filter(c=>c.sex==='male').length||0} / ${f?.children.filter(c=>c.sex==='female').length||0}</strong></div><div class="metric-row"><span>Marriage ready</span><strong>${eligible.length}</strong></div>${due?`<p class="dialog-intro">A child is expected in ${months[due%12]} ${Math.floor(due/12)}.</p>`:''}<div class="royal-children">${rows||'<p class="dialog-intro">No children recorded.</p>'}</div><p class="dialog-intro">Unmarried rulers may marry a court consort through Diplom, or receive a royal proposal. Princesses marry male rulers; princes marry female rulers. Children become eligible at 16. All families use the same 3% monthly chance of an expected birth when married and age-eligible, nine-month gestation and twelve-month birth cooldown. Births require both spouses aged 18+, with the mother no older than 45 and father no older than 65.</p>`:`<p class="dialog-intro">Original family rules</p><div class="metric-row"><span>Daughters</span><strong>${r.hasDaughter===false?0:1}</strong></div><div class="metric-row"><span>Marriage daughter</span><strong>${r.hasDaughter===false?'Unavailable':r.daughterGivenTo===undefined?'Available':'Married to '+esc(game.ruler(r.daughterGivenTo)?.name||'a former ruler')}</strong></div><p class="dialog-intro">The original daughter slot is independent of receiving a spouse. No numerical child ages or birth schedule are tracked.</p>`,`<button id="closeFamily">Close</button>${!expanded&&r.id===game.s.player?'<button id="expandFamily" class="gold-button">Enable Expanded family</button>':''}`,'ROYAL FAMILY');
 $('closeFamily').onclick=close;$('expandFamily')?.addEventListener('click',()=>{game.s.familyMode='expanded';initializeRoyalFamilies(game.s);save();royalFamilyDialog(id);});
}
function triumphDialog(){const t=game.s.triumph,p=game.province(t.province);dialog('Victory',`<div class="triumph-scene"><canvas id="triumphArtwork" data-atlas="triumph" data-cell="0" role="img" aria-label="A victorious army celebrates before the captured city"></canvas><div class="triumph-copy"><strong>${esc(name(game.ruler(t.owner)))}</strong><h2>#${p.id} · ${esc(p.name)}</h2><p>Day ${t.day} · ${esc(t.reason)}</p><p>${t.captured} captured ${t.captured===1?'general':'generals'}</p></div></div>`,'<button id="continueTriumph" class="gold-button">Continue</button>','TRIUMPH');$('dialog').classList.add('triumph-dialog');$('continueTriumph').onclick=()=>{game.acknowledgeTriumph();$('dialog').classList.remove('triumph-dialog');$('dialog').close();refresh();};}
function showPendingDecisions(){
 if(!game||$('game').hidden||$('dialog').open||battleMessages.busy)return;
 if(game.s.triumph){triumphDialog();return;}
 if(game.s.allyDecisions.length){alliedDecisionDialog();return;}
 const succession=game.s.successorDecisions.find(x=>game.isHuman(x.owner));if(succession){dialog('Choose the next ruler',`<p class="dialog-intro">${esc(succession.name)} has died. Choose the successor for this realm.</p><div class="suborder-grid">${succession.candidates.map(id=>{const o=game.officer(id);return `<button data-successor="${id}">${portraitMarkup(o,'portrait-mini')}<strong>${esc(o.name)}</strong><span class="general-stats">${generalStats(o,'recruit')}</span></button>`;}).join('')}</div>`,'','SUCCESSION');$('dialogBody').querySelectorAll('[data-successor]').forEach(b=>b.onclick=()=>{game.chooseSuccessor(succession.owner,Number(b.dataset.successor));$('dialog').close();refresh();});return;}
 const j=game.s.journey;
 if(j&&(game.isHuman(j.owner)||j.interception&&game.isHuman(j.interception.owner))){
  const leg=j.legs[j.leg],o=game.officer(leg.officer),intercept=j.interception,owner=intercept?game.ruler(intercept.owner):game.ruler(j.owner);
  dialog(intercept?'Messenger intercepted':'Mounted messenger',`<div class="courier-scene"><canvas data-atlas="courier" data-cell="0" class="courier-animation" role="img" aria-label="Mounted courier galloping"></canvas><div><strong>${esc(o.name)}</strong><span>${j.phase==='return'?'Returning':'Outbound'} · Province ${leg.route[leg.index]}</span></div></div><p class="journey-route">${leg.route.map((id,i)=>`<span class="${i===leg.index?'active':''}">${id}</span>`).join('')}</p><p class="dialog-intro">${intercept?`${esc(owner.name)} intercepted this messenger in Province ${intercept.province}. Decide their fate.`:j.phase==='return'?esc(j.result||'The audience is complete. The messenger is returning.'):`${esc(owner.name)}’s messenger is travelling between the numbered cities.`}</p><p id="journeyError" class="form-error" role="alert"></p>`,intercept?'<button id="freeMessenger">Set free</button><button id="captureMessenger">Capture</button><button id="beheadMessenger" class="danger-button">Behead</button>':'<button id="continueJourney" class="gold-button">Continue journey</button>','MESSENGER');
  const run=fn=>{try{fn();$('dialog').close();refresh();}catch(e){const error=$('journeyError');if(error)error.textContent=e.message;else toast(e.message);}};
  if(intercept){$('freeMessenger').onclick=()=>run(()=>game.interceptJourney('free'));$('captureMessenger').onclick=()=>run(()=>game.interceptJourney('capture'));$('beheadMessenger').onclick=()=>confirmExecution(o.name,()=>run(()=>game.interceptJourney('behead')));}
  else $('continueJourney').onclick=()=>run(()=>game.advanceJourney());return;
 }
 const c=game.s.captiveDecisions.find(c=>game.isHuman(c.owner));if(!c){if(game.s.spoils.length)spoilsDialog();return;}const o=game.officer(c.officer),owner=game.ruler(c.owner);
 dialog('Decide the captive’s fate',`<div class="captive-card">${portraitMarkup(o,'dialog-portrait')}<div><h3>${esc(name(o))}</h3><p>${esc(c.role)} · Province ${c.province}</p><div class="general-stats">${generalStats(o,'recruit')}</div></div></div><p class="dialog-intro">${esc(name(owner))} decides. ${game.s.captiveDecisions.filter(x=>x.owner===c.owner).length} captive decisions remain.</p>${c.recruitTried?'<p class="form-error">Recruitment was refused. Choose Set free or Behead.</p>':''}<p id="captiveError" class="form-error" role="alert"></p>`,`<button id="recruitCaptive" class="gold-button" ${c.recruitTried?'disabled':''}>Recruit</button><button id="freeCaptive">Set free</button><button id="beheadCaptive" class="danger-button">Behead</button>`,'CAPTIVES');
 const run=action=>{try{game.decideCaptive(c.officer,action);$('dialog').close();refresh();}catch(e){const error=$('captiveError');if(error)error.textContent=e.message;else toast(e.message);}};
 $('recruitCaptive').onclick=()=>run('recruit');$('freeCaptive').onclick=()=>run('free');$('beheadCaptive').onclick=()=>confirmExecution(name(o),()=>run('behead'));
}
function confirmExecution(person,action){dialog('Confirm execution',`<p class="dialog-intro">Behead ${esc(person)}? This officer will be removed from the campaign.</p>`,'<button id="cancelExecution">Return to decision</button><button id="confirmExecution" class="danger-button">Behead</button>','CONFIRM');$('cancelExecution').onclick=()=>{$('dialog').close();showPendingDecisions();};$('confirmExecution').onclick=action;}
function renderExileOrders(){
 const party=game.roaming();if(!party)return;paneView='orders';$('panelBody').hidden=false;$('expandEvent').hidden=true;$('panelBody').innerHTML=`<h2 class="approach-title">Ruler in exile · #${party.province}</h2><p class="dialog-intro">${party.officers.length} generals · ${num(party.gold)} gold · ${num(party.food)} food</p><div class="province-orders exile-orders">${['Move','View','Settle','Rest'].map(label=>`<button data-exile-order="${label.toLowerCase()}" class="${label==='Settle'&&game.province(party.province).owner!==255?'order-unavailable':''}">${label}</button>`).join('')}</div>`;
 $('panelBody').querySelectorAll('[data-exile-order]').forEach(button=>button.onclick=()=>{const type=button.dataset.exileOrder;if(type==='view'){dialog('View in exile','<div class="suborder-grid"><button id="exileProvince">This province</button><button id="exileGenerals">Generals</button><button id="exileList">List of generals</button></div>','','EXILE');$('exileProvince').onclick=()=>{close();navigate('province');};$('exileGenerals').onclick=()=>{dialog('Generals in exile',party.officers.map(id=>`<button class="officer-card list-row" data-exile-general="${id}">${portraitMarkup(game.officer(id),'portrait-mini')}<strong>${esc(game.officer(id).name)}</strong><span class="general-stats">${generalStats(game.officer(id))}</span></button>`).join(''),'','EXILE');$('dialogBody').querySelectorAll('[data-exile-general]').forEach(b=>b.onclick=()=>officerDialog(Number(b.dataset.exileGeneral)));};$('exileList').onclick=()=>{dialog('Generals in exile',party.officers.map(id=>`<div class="list-row"><strong>${esc(game.officer(id).name)}</strong><div class="general-stats">${generalStats(game.officer(id))}</div></div>`).join(''),'','EXILE');};return;}if(type==='move'){dialog('Move where?',selectField('exileDestination','Connected province',options(game.province(party.province).neighbors.map(id=>provinceChoice(game,game.province(id))))),'<button id="travelExile" class="gold-button">Move</button>','EXILE');$('travelExile').onclick=()=>{game.roam('move',Number($('exileDestination').value));close();refresh();};return;}dialog(type==='settle'?'Settle here?':'Rest here?',`<p class="dialog-intro">${type==='settle'?'Settle in Province '+party.province+'? The province must be unoccupied.':'Finish this month’s exile orders?'}</p><p id="exileError" class="form-error"></p>`,'<button id="cancelExileOrder">No</button><button id="confirmExileOrder" class="gold-button">Yes</button>','EXILE');$('cancelExileOrder').onclick=close;$('confirmExileOrder').onclick=()=>{try{game.roam(type);close();refresh();}catch(e){$('exileError').textContent=e.message;}};});
}
setInterval(()=>{if(document.hidden)return;for(const canvas of document.querySelectorAll('.courier-animation')){canvas.dataset.cell=String(Math.floor(performance.now()/130)%4);}if(document.querySelector('.courier-animation'))artwork?.refresh();},130);

function restProvinceDialog(){const p=selected(),remaining=p.officers.filter(id=>!game.officer(id).acted).length;dialog('Rest in this province?',`<p class="dialog-intro">Province ${p.id} has ${remaining} unused generals. Finish its orders and continue to the next directly ruled province?</p>`,'<button id="keepPlaying">Keep playing</button><button id="advanceMonth" class="gold-button">Rest</button>','PROVINCE COUNCIL');$('keepPlaying').onclick=close;$('advanceMonth').onclick=()=>{try{game.restProvince(p.id);close();refresh();}catch(e){toast(e.message);}};}
function setupScenario(){const s=structuredClone(scenarios[setup.scenario]);if(setup.custom)createCustomRuler(s,setup.custom);return s;}
function customRulerDialog(){const s=scenarios[setup.scenario],x=setup.custom||{};dialog('Create a ruler',`<div class="field"><label for="customName">Ruler name</label><input id="customName" maxlength="12" value="${esc(x.name||'New Ruler')}"></div><div class="field"><label for="customFollower">Follower name</label><input id="customFollower" maxlength="12" value="${esc(x.follower||'Companion')}"></div>${selectField('customProvince','Starting province',options(s.provinces.filter(p=>p.owner===255).map(p=>[p.id,'#'+p.id+' · '+p.name+' · Unclaimed'])))}${selectField('customSex','Sex',options([['male','Male'],['female','Female']]))}${numberField('customAge','Age',1,99,x.age||25)}${['int','war','charm'].map(k=>numberField('custom'+k,k.toUpperCase(),1,100,x[k]||70)).join('')}<p class="dialog-intro">250 total ability points. A loyal follower joins you. Two 1,000-man units, at least 1,000 gold and 20,000 food.</p><p id="customError" class="form-error"></p>`,'<button id="cancelCustom">Cancel</button><button id="confirmCustom" class="gold-button">Create</button>','NEW RULER');$('cancelCustom').onclick=close;if(x.province)$('customProvince').value=x.province;$('customSex').value=x.sex||'male';$('confirmCustom').onclick=()=>{try{const spec={name:$('customName').value,follower:$('customFollower').value,province:Number($('customProvince').value),age:Number($('customAge').value),sex:$('customSex').value,...Object.fromEntries(['int','war','charm'].map(k=>[k,Number($('custom'+k).value)]))},test=structuredClone(s),id=createCustomRuler(test,spec);setup.custom=spec;setup.humans[setup.humanIndex]=id;close();renderSetup();}catch(e){$('customError').textContent=e.message;}};}
function alliedDecisionDialog(){const x=game.s.allyDecisions[0],owner=game.ruler(x.owner),sender=game.ruler(x.requester);
 if(x.route&&x.index<x.route.length-1){dialog('Mounted request for support',`<div class="courier-scene"><canvas data-atlas="courier" data-cell="0" class="courier-animation" role="img" aria-label="Mounted messenger"></canvas><strong>${esc(sender.name)} asks ${esc(owner.name)}</strong></div><p class="journey-route">${x.route.map((id,i)=>`<span class="${i===x.index?'active':''}">${id}</span>`).join('')}</p>`,'<button id="continueSupport" class="gold-button">Continue journey</button>','ALLIED SUPPORT');$('continueSupport').onclick=()=>{x.index++;$('dialog').close();refresh();};return;}
 if(!game.isHuman(x.owner)){aiAlly(game);refresh();return;}
 const candidates=supportCandidates(game,x);dialog('Answer allied request',`<p class="dialog-intro">${esc(sender.name)} requests ${x.kind==='joint'?'joint invasion':'battle'} support in Province ${x.province}. ${esc(owner.name)}, send troops? Refusal costs 5 trust.</p><div class="commander-list">${candidates.map(({id,province})=>`<label><input type="checkbox" name="allyCommander" value="${id}"><span>${portraitMarkup(game.officer(id),'portrait-mini')}<strong>${esc(game.officer(id).name)} · #${province}</strong><span class="general-stats">${generalStats(game.officer(id),'war')}</span></span></label>`).join('')}</div>${numberField('alliedFood','Food from first selected province',0,3000000,0)}${numberField('alliedGold','Gold from first selected province',0,30000,0)}<p class="dialog-intro">Select 1–5 commanders; leave a governor in each contributing province.</p><p id="allyError" class="form-error"></p>`,'<button id="refuseAlly">Refuse</button><button id="acceptAlly" class="gold-button">Send support</button>','ALLIED SUPPORT');const answer=accept=>{try{game.answerAlly(accept,{officers:[...document.querySelectorAll('input[name=allyCommander]:checked')].map(n=>Number(n.value)),food:Number($('alliedFood').value),gold:Number($('alliedGold').value)});$('dialog').close();refresh();}catch(e){$('allyError').textContent=e.message;}};$('refuseAlly').onclick=()=>answer(false);$('acceptAlly').onclick=()=>answer(true);}
function spoilsDialog(){const x=game.s.spoils[0];if(!x)return;if(!game.isHuman(x.owner)){game.decideSpoils('protect',game.province(x.province).governor);refresh();return;}const p=game.province(x.province),item=ITEMS.find(i=>i.id===x.item);dialog('Victory in Province '+p.id,`<p class="dialog-intro">Protect the inhabitants, or plunder food and gold at the cost of 20 popular loyalty and 10 ruler trust?</p>${item?`<p>${esc(item.name)} was found in the captured castle. ${esc(item.stat.toUpperCase())} +${item.bonus}.</p>${selectField('treasureRecipient','Give the treasure to whom?',options(p.officers.map(id=>[id,game.officer(id).name])))}`:''}<p id="spoilsError" class="form-error"></p>`,'<button id="protectProvince" class="gold-button">Protect</button><button id="plunderProvince" class="danger-button">Plunder</button>','VICTORY');const decide=mode=>{try{game.decideSpoils(mode,item?Number($('treasureRecipient').value):p.governor);$('dialog').close();refresh();}catch(e){$('spoilsError').textContent=e.message;}};$('protectProvince').onclick=()=>decide('protect');$('plunderProvince').onclick=()=>decide('plunder');}

document.addEventListener('visibilitychange',syncPlayback);
